INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-5-01', 'ngsl-5', 'Thông dụng 2.001–2.500 · Bộ 1', 'New General Service List, thứ hạng 2.001–2.500', '#3da9fc', 'BookOpen', 1);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-01', 1, 'achievement', 'thành tích; thành tựu', 'noun', '[{"en":"Winning the scholarship was the greatest achievement of her school years.","vi":"Giành được học bổng là thành tích lớn nhất trong những năm đi học của cô ấy."},{"en":"Learning to swim at sixty is a great achievement.","vi":"Học bơi ở tuổi sáu mươi là một thành tựu lớn."},{"en":"Finishing my first marathon gave me a real sense of achievement.","vi":"Hoàn thành cuộc chạy marathon đầu tiên mang lại cho tôi cảm giác thành tựu thực sự."}]', '[{"phrase":"great achievement"},{"phrase":"sense of achievement"},{"phrase":"academic achievement"}]', NULL, '/əˈtʃiːvmənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ach/achie/achievement__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-01', 2, 'negotiate', 'đàm phán; thương lượng', 'verb', '[{"en":"We negotiated a lower rent with our landlord last month.","vi":"Tháng trước chúng tôi đã thương lượng được mức tiền thuê nhà thấp hơn với chủ nhà."},{"en":"The two companies are still trying to negotiate a deal.","vi":"Hai công ty vẫn đang cố gắng đàm phán một thỏa thuận."},{"en":"Don''t be afraid to negotiate your salary when you get a job offer.","vi":"Đừng ngại thương lượng mức lương khi bạn nhận được lời mời làm việc."}]', '[{"phrase":"negotiate a deal"},{"phrase":"negotiate a contract"},{"phrase":"negotiate with"}]', NULL, '/nɪˈɡəʊʃieɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/neg/negot/negotiate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-01', 3, 'dominate', 'chiếm ưu thế; chi phối; thống trị', 'verb', '[{"en":"Our team dominated the game from start to finish.","vi":"Đội chúng tôi chiếm ưu thế trong trận đấu từ đầu đến cuối."},{"en":"Money worries dominated his life after he lost his job.","vi":"Nỗi lo tiền bạc chi phối cuộc sống của anh ấy sau khi mất việc."},{"en":"A few large companies dominate the market for mobile phones.","vi":"Một vài công ty lớn thống trị thị trường điện thoại di động."}]', '[{"phrase":"dominate the market"},{"phrase":"dominate the conversation"},{"phrase":"dominate the news"}]', NULL, '/ˈdɑːmɪneɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dom/domin/dominate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-01', 4, 'supplier', 'nhà cung cấp', 'noun', '[{"en":"We found a cheaper supplier for our office paper.","vi":"Chúng tôi đã tìm được một nhà cung cấp giấy văn phòng rẻ hơn."},{"en":"The restaurant buys fresh vegetables from a local supplier every morning.","vi":"Nhà hàng mua rau tươi từ một nhà cung cấp địa phương mỗi sáng."},{"en":"If our supplier delivers late again, we will have to find another one.","vi":"Nếu nhà cung cấp lại giao hàng trễ, chúng ta sẽ phải tìm nhà cung cấp khác."}]', '[{"phrase":"local supplier"},{"phrase":"main supplier"},{"phrase":"energy supplier"}]', NULL, '/səˈplaɪər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sup/suppl/supplier__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-01', 5, 'prize', 'giải thưởng; phần thưởng', 'noun', '[{"en":"She won first prize in the school drawing contest.","vi":"Cô ấy đã giành giải nhất trong cuộc thi vẽ của trường."},{"en":"The prize for the winning team is a trip to the beach.","vi":"Giải thưởng cho đội chiến thắng là một chuyến đi biển."},{"en":"Everyone who finishes the race will get a small prize.","vi":"Tất cả những ai hoàn thành cuộc đua sẽ nhận được một phần thưởng nhỏ."}]', '[{"phrase":"win a prize"},{"phrase":"first prize"},{"phrase":"prize money"}]', NULL, '/praɪz/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pri/prize/prize__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-01', 6, 'typically', 'thường; thông thường; một cách điển hình', 'adverb', '[{"en":"The trip typically takes about three hours by train.","vi":"Chuyến đi bằng tàu hỏa thường mất khoảng ba tiếng."},{"en":"Typically, we have dinner together at seven o''clock.","vi":"Thông thường, chúng tôi ăn tối cùng nhau lúc bảy giờ."},{"en":"The weather was typically cold and wet for November.","vi":"Thời tiết lạnh và ẩm ướt, đúng kiểu điển hình của tháng Mười Một."}]', '[{"phrase":"typically take"},{"phrase":"typically include"},{"phrase":"typically used"}]', NULL, '/ˈtɪpɪkli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/typ/typic/typically__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-01', 7, 'peer', 'bạn đồng trang lứa; người ngang hàng; đồng nghiệp', 'noun', '[{"en":"Teenagers often care a lot about what their peers think.","vi":"Thanh thiếu niên thường rất quan tâm đến suy nghĩ của bạn bè đồng trang lứa."},{"en":"Peer pressure can make children do things they don''t want to do.","vi":"Áp lực từ bạn bè có thể khiến trẻ làm những việc mà chúng không muốn làm."},{"en":"New staff are trained by their peers during the first week.","vi":"Nhân viên mới được các đồng nghiệp đào tạo trong tuần đầu tiên."}]', '[{"phrase":"peer pressure"},{"phrase":"peer group"},{"phrase":"peer support"}]', NULL, '/pɪr/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pee/peer_/peer__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-01', 8, 'pension', 'lương hưu', 'noun', '[{"en":"My grandfather lives on a small pension.","vi":"Ông tôi sống bằng một khoản lương hưu nhỏ."},{"en":"She will start receiving her pension when she turns sixty.","vi":"Bà ấy sẽ bắt đầu nhận lương hưu khi tròn sáu mươi tuổi."},{"en":"Many workers pay into a pension plan through their company.","vi":"Nhiều người lao động đóng tiền vào chương trình hưu trí thông qua công ty của họ."}]', '[{"phrase":"pension plan"},{"phrase":"receive a pension"},{"phrase":"pension fund"}]', NULL, '/ˈpɛnʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-01', 9, 'wing', 'cánh (chim, máy bay); dãy nhà', 'noun', '[{"en":"The bird hurt its wing and could not fly.","vi":"Con chim bị thương ở cánh và không thể bay."},{"en":"From my window seat, I could only see the plane''s wing.","vi":"Từ ghế cạnh cửa sổ, tôi chỉ có thể nhìn thấy cánh máy bay."},{"en":"The children''s ward is in the east wing of the hospital.","vi":"Khoa nhi nằm ở dãy nhà phía đông của bệnh viện."}]', '[{"phrase":"east wing"},{"phrase":"chicken wings"},{"phrase":"spread its wings"}]', NULL, '/wɪŋ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/win/wing_/wing__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-01', 10, 'acquisition', 'sự mua lại; sự tiếp thu; vật mới mua được', 'noun', '[{"en":"The acquisition of the smaller company took almost a year.","vi":"Việc mua lại công ty nhỏ hơn mất gần một năm."},{"en":"Language acquisition is much faster in young children than in adults.","vi":"Việc tiếp thu ngôn ngữ ở trẻ nhỏ nhanh hơn nhiều so với ở người lớn."},{"en":"The museum''s latest acquisition is a painting from the 1800s.","vi":"Hiện vật mới nhất mà bảo tàng mua về là một bức tranh từ thế kỷ 19."}]', '[{"phrase":"language acquisition"},{"phrase":"acquisition of"},{"phrase":"recent acquisition"}]', NULL, '/ˌækwɪˈzɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/acq/acqui/acquisition__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-01', 11, 'laughter', 'tiếng cười; sự cười đùa', 'noun', '[{"en":"We could hear laughter coming from the kitchen.","vi":"Chúng tôi có thể nghe thấy tiếng cười vọng ra từ nhà bếp."},{"en":"The whole audience burst into laughter at his joke.","vi":"Cả khán giả bật cười trước câu đùa của anh ấy."},{"en":"They say laughter is the best medicine.","vi":"Người ta nói tiếng cười là liều thuốc tốt nhất."}]', '[{"phrase":"burst into laughter"},{"phrase":"loud laughter"},{"phrase":"full of laughter"}]', 'không đếm được', '/ˈlæftər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lau/laugh/laughter__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-01', 12, 'deeply', 'vô cùng; sâu sắc; sâu', 'adverb', '[{"en":"I was deeply moved by her kind letter.","vi":"Tôi vô cùng xúc động trước lá thư đầy tử tế của cô ấy."},{"en":"He is deeply sorry for what he said.","vi":"Anh ấy vô cùng hối hận về những gì mình đã nói."},{"en":"Take a moment to breathe deeply before you start speaking.","vi":"Hãy dành chút thời gian hít thở sâu trước khi bắt đầu nói."}]', '[{"phrase":"deeply moved"},{"phrase":"breathe deeply"},{"phrase":"deeply concerned"}]', NULL, '/ˈdiːpli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dee/deepl/deeply__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-01', 13, 'recognition', 'sự công nhận; sự nhận ra', 'noun', '[{"en":"She finally received recognition for her years of hard work.","vi":"Cuối cùng cô ấy cũng được công nhận cho nhiều năm làm việc chăm chỉ."},{"en":"He was given an award in recognition of his service.","vi":"Ông ấy được trao giải thưởng để ghi nhận những cống hiến của mình."},{"en":"The town has changed beyond recognition since I was a child.","vi":"Thị trấn đã thay đổi đến mức không thể nhận ra kể từ khi tôi còn nhỏ."}]', '[{"phrase":"in recognition of"},{"phrase":"receive recognition"},{"phrase":"beyond recognition"}]', NULL, '/ˌrekəɡˈnɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rec/recog/recognition__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-01', 14, 'electricity', 'điện', 'noun', '[{"en":"The storm left the whole village without electricity for two days.","vi":"Cơn bão khiến cả làng bị mất điện suốt hai ngày."},{"en":"Turn off the lights when you leave to save electricity.","vi":"Hãy tắt đèn khi ra ngoài để tiết kiệm điện."},{"en":"Our electricity bill is much higher in the summer.","vi":"Hóa đơn tiền điện của chúng tôi cao hơn nhiều vào mùa hè."}]', '[{"phrase":"electricity bill"},{"phrase":"save electricity"},{"phrase":"generate electricity"}]', 'không đếm được', '/ɪˌlekˈtrɪsəti/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ele/elect/electricity__us_6.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-01', 15, 'assistance', 'sự giúp đỡ; sự hỗ trợ', 'noun', '[{"en":"Please call the front desk if you need any assistance.","vi":"Vui lòng gọi cho quầy lễ tân nếu bạn cần hỗ trợ."},{"en":"The school offers financial assistance to students from poor families.","vi":"Nhà trường hỗ trợ tài chính cho học sinh từ các gia đình nghèo."},{"en":"With the assistance of a neighbor, she moved the heavy sofa.","vi":"Nhờ sự giúp đỡ của một người hàng xóm, cô ấy đã chuyển được chiếc ghế sofa nặng."}]', '[{"phrase":"financial assistance"},{"phrase":"with the assistance of"},{"phrase":"provide assistance"}]', 'không đếm được', '/əˈsɪstəns/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ass/assis/assistance__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-01', 16, 'roof', 'mái nhà', 'noun', '[{"en":"The roof leaks every time it rains heavily.","vi":"Mái nhà bị dột mỗi khi trời mưa to."},{"en":"We climbed onto the roof to watch the fireworks.","vi":"Chúng tôi trèo lên mái nhà để xem pháo hoa."},{"en":"My cousin and I grew up under the same roof.","vi":"Tôi và anh họ lớn lên dưới cùng một mái nhà."}]', '[{"phrase":"on the roof"},{"phrase":"under the same roof"},{"phrase":"leaking roof"}]', NULL, '/ruːf/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/roo/roof_/roof__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-01', 17, 'retirement', 'sự nghỉ hưu; tuổi nghỉ hưu', 'noun', '[{"en":"My parents are planning to travel a lot in retirement.","vi":"Bố mẹ tôi dự định sẽ đi du lịch nhiều khi nghỉ hưu."},{"en":"She announced her retirement after thirty years of teaching.","vi":"Bà ấy tuyên bố nghỉ hưu sau ba mươi năm dạy học."},{"en":"It is never too early to start saving for retirement.","vi":"Không bao giờ là quá sớm để bắt đầu tiết kiệm cho tuổi nghỉ hưu."}]', '[{"phrase":"early retirement"},{"phrase":"retirement age"},{"phrase":"in retirement"}]', NULL, '/rɪˈtaɪərmənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/ret/retir/retirement__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-01', 18, 'respectively', 'lần lượt; tương ứng', 'adverb', '[{"en":"My two sons are six and nine years old, respectively.","vi":"Hai con trai tôi lần lượt sáu và chín tuổi."},{"en":"Coffee and tea cost three and two dollars, respectively.","vi":"Cà phê và trà có giá lần lượt là ba và hai đô la."},{"en":"The morning and evening classes start at eight and six, respectively.","vi":"Lớp buổi sáng và buổi tối lần lượt bắt đầu lúc tám giờ và sáu giờ."}]', '[{"phrase":"A and B, respectively"},{"phrase":"rose by 5% and 8%, respectively"}]', 'Thường đứng cuối câu, sau các mục liệt kê theo thứ tự', '/rɪˈspektɪvli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/res/respe/respectively__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-01', 19, 'variation', 'sự thay đổi; sự khác biệt; biến thể', 'noun', '[{"en":"There is little variation in temperature here throughout the year.","vi":"Ở đây nhiệt độ ít thay đổi trong suốt cả năm."},{"en":"This recipe is a variation on a traditional family dish.","vi":"Công thức này là một biến thể của một món ăn truyền thống trong gia đình."},{"en":"Prices show a lot of variation from one shop to another.","vi":"Giá cả khác biệt khá nhiều giữa cửa hàng này với cửa hàng khác."}]', '[{"phrase":"variation in"},{"phrase":"variation on"},{"phrase":"wide variation"}]', NULL, '/ˌveriˈeɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/var/varia/variation__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-01', 20, 'ultimately', 'cuối cùng; rốt cuộc', 'adverb', '[{"en":"Ultimately, the decision is yours to make.","vi":"Rốt cuộc thì quyết định vẫn là ở bạn."},{"en":"We tried several plans, but ultimately we had to cancel the trip.","vi":"Chúng tôi đã thử vài kế hoạch, nhưng cuối cùng vẫn phải hủy chuyến đi."},{"en":"Hard work will ultimately lead to success.","vi":"Làm việc chăm chỉ cuối cùng sẽ dẫn đến thành công."}]', '[{"phrase":"ultimately responsible"},{"phrase":"ultimately lead to"},{"phrase":"ultimately decide"}]', NULL, '/ˈʌltɪmətli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/ult/ultim/ultimately__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-01', 21, 'proof', 'bằng chứng; giấy tờ chứng minh', 'noun', '[{"en":"You need proof of address to open a bank account.","vi":"Bạn cần giấy tờ chứng minh địa chỉ để mở tài khoản ngân hàng."},{"en":"There is no proof that he took the money.","vi":"Không có bằng chứng nào cho thấy anh ta đã lấy tiền."},{"en":"Keep your receipt as proof of purchase.","vi":"Hãy giữ hóa đơn làm bằng chứng mua hàng."}]', '[{"phrase":"proof of purchase"},{"phrase":"proof of identity"},{"phrase":"no proof"}]', NULL, '/pruːf/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/proof/proof__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-01', 22, 'soil', 'đất; đất trồng', 'noun', '[{"en":"Carrots grow well in soft, sandy soil.","vi":"Cà rốt phát triển tốt trong đất cát tơi xốp."},{"en":"The soil in our garden is too dry for roses.","vi":"Đất trong vườn nhà chúng tôi quá khô để trồng hoa hồng."},{"en":"Push the seeds gently into the soil and water them.","vi":"Nhẹ nhàng ấn hạt giống xuống đất rồi tưới nước."}]', '[{"phrase":"rich soil"},{"phrase":"sandy soil"},{"phrase":"dry soil"}]', NULL, '/sɔɪl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/soi/soil_/soil__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-01', 23, 'smart', 'thông minh; khôn ngoan; bảnh bao', 'adjective', '[{"en":"She is a smart student who learns new things quickly.","vi":"Cô ấy là một học sinh thông minh, học điều mới rất nhanh."},{"en":"Bringing an umbrella today was a smart move.","vi":"Mang theo ô hôm nay là một quyết định khôn ngoan."},{"en":"He looked very smart in his new suit.","vi":"Anh ấy trông rất bảnh bao trong bộ vest mới."}]', '[{"phrase":"smart move"},{"phrase":"smart choice"},{"phrase":"look smart"}]', NULL, '/smɑːrt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sma/smart/smart__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-01', 24, 'layer', 'lớp; tầng', 'noun', '[{"en":"A thin layer of dust covered the old piano.","vi":"Một lớp bụi mỏng phủ lên chiếc đàn piano cũ."},{"en":"Wear several layers of clothing when you go hiking in winter.","vi":"Hãy mặc nhiều lớp quần áo khi đi bộ đường dài vào mùa đông."},{"en":"The cake has three layers with cream between them.","vi":"Chiếc bánh có ba tầng với kem ở giữa."}]', '[{"phrase":"thin layer"},{"phrase":"layer of dust"},{"phrase":"outer layer"},{"phrase":"top layer"}]', NULL, '/ˈleɪər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lay/layer/layer__us_4.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-01', 25, 'upset', 'buồn bực; khó chịu; lo lắng', 'adjective', '[{"en":"She was upset because nobody remembered her birthday.","vi":"Cô ấy buồn vì không ai nhớ sinh nhật mình."},{"en":"Don''t get upset about such a small mistake.","vi":"Đừng bực mình vì một lỗi nhỏ như vậy."},{"en":"My little brother gets upset whenever he loses a game.","vi":"Em trai tôi hay khó chịu mỗi khi thua một trò chơi."}]', '[{"phrase":"get upset"},{"phrase":"upset about"},{"phrase":"upset stomach"}]', 'Động từ: upset – upset – upset', '/ˌʌpˈset/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/ups/upset/upset__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-01', 26, 'tooth', 'răng', 'noun', '[{"en":"I broke a tooth while eating hard candy.","vi":"Tôi bị gãy một chiếc răng khi ăn kẹo cứng."},{"en":"Remember to brush your teeth before going to bed.","vi":"Hãy nhớ đánh răng trước khi đi ngủ."},{"en":"My daughter lost her first baby tooth last night.","vi":"Con gái tôi bị rụng chiếc răng sữa đầu tiên tối qua."}]', '[{"phrase":"brush your teeth"},{"phrase":"baby tooth"},{"phrase":"wisdom tooth"},{"phrase":"sweet tooth"}]', 'Số nhiều: teeth', '/tuːθ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/too/tooth/tooth__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-01', 27, 'representation', 'sự đại diện; sự thể hiện', 'noun', '[{"en":"The workers asked for fair representation in talks with management.","vi":"Công nhân yêu cầu được đại diện công bằng trong các cuộc đàm phán với ban quản lý."},{"en":"The painting is a representation of life in a small village.","vi":"Bức tranh là sự thể hiện cuộc sống ở một ngôi làng nhỏ."},{"en":"This map gives a simple representation of the city''s bus routes.","vi":"Bản đồ này thể hiện một cách đơn giản các tuyến xe buýt của thành phố."}]', '[{"phrase":"fair representation"},{"phrase":"legal representation"},{"phrase":"visual representation"}]', NULL, '/ˌreprɪzenˈteɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rep/repre/representation__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-01', 28, 'preparation', 'sự chuẩn bị', 'noun', '[{"en":"The wedding took months of careful preparation.","vi":"Đám cưới mất nhiều tháng chuẩn bị kỹ lưỡng."},{"en":"We bought extra water in preparation for the storm.","vi":"Chúng tôi mua thêm nước để chuẩn bị cho cơn bão."},{"en":"Good preparation is the key to passing any exam.","vi":"Chuẩn bị tốt là chìa khóa để vượt qua bất kỳ kỳ thi nào."}]', '[{"phrase":"in preparation for"},{"phrase":"careful preparation"},{"phrase":"exam preparation"}]', NULL, '/ˌprepəˈreɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pre/prepa/preparation__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-01', 29, 'dispute', 'cuộc tranh chấp; sự bất đồng', 'noun', '[{"en":"The two neighbors had a long dispute over the fence.","vi":"Hai người hàng xóm đã có một cuộc tranh chấp kéo dài về hàng rào."},{"en":"The company settled the dispute with its workers last week.","vi":"Tuần trước công ty đã giải quyết xong tranh chấp với công nhân."},{"en":"The ownership of the house is still in dispute.","vi":"Quyền sở hữu ngôi nhà vẫn đang bị tranh chấp."}]', '[{"phrase":"settle a dispute"},{"phrase":"dispute over"},{"phrase":"in dispute"},{"phrase":"legal dispute"}]', NULL, '/dɪˈspjuːt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dis/dispu/dispute__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-01', 30, 'agenda', 'chương trình họp; chương trình nghị sự; ưu tiên cần làm', 'noun', '[{"en":"What''s the first item on the agenda for today''s meeting?","vi":"Mục đầu tiên trong chương trình họp hôm nay là gì?"},{"en":"Please send me the agenda before the meeting starts.","vi":"Vui lòng gửi cho tôi chương trình họp trước khi cuộc họp bắt đầu."},{"en":"Saving money is high on my agenda this year.","vi":"Tiết kiệm tiền là ưu tiên hàng đầu của tôi trong năm nay."}]', '[{"phrase":"on the agenda"},{"phrase":"set the agenda"},{"phrase":"item on the agenda"}]', NULL, '/əˈdʒendə/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/age/agend/agenda__us_2.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-5-02', 'ngsl-5', 'Thông dụng 2.001–2.500 · Bộ 2', 'New General Service List, thứ hạng 2.001–2.500', '#3da9fc', 'BookOpen', 2);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-02', 1, 'emphasis', 'sự nhấn mạnh; sự chú trọng', 'noun', '[{"en":"Our school puts a strong emphasis on reading every day.","vi":"Trường chúng tôi rất chú trọng việc đọc sách mỗi ngày."},{"en":"The new manager places more emphasis on teamwork than before.","vi":"Quản lý mới coi trọng tinh thần làm việc nhóm hơn trước."},{"en":"She said the last word with extra emphasis.","vi":"Cô ấy nhấn mạnh hơn ở từ cuối cùng."}]', '[{"phrase":"put emphasis on"},{"phrase":"place emphasis on"},{"phrase":"strong emphasis"},{"phrase":"special emphasis"}]', 'emphasis on sth; số nhiều: emphases', '/ˈemfəsɪs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/emp/empha/emphasis__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-02', 2, 'edition', 'ấn bản; số (báo)', 'noun', '[{"en":"I bought the latest edition of the travel guide before my trip.","vi":"Tôi đã mua ấn bản mới nhất của cuốn sách hướng dẫn du lịch trước chuyến đi."},{"en":"This book is a first edition, so it is worth a lot.","vi":"Cuốn sách này là ấn bản đầu tiên nên rất có giá trị."},{"en":"The story appeared in the Sunday edition of the local newspaper.","vi":"Câu chuyện được đăng trên số Chủ nhật của tờ báo địa phương."}]', '[{"phrase":"new edition"},{"phrase":"latest edition"},{"phrase":"first edition"},{"phrase":"limited edition"}]', 'edition (ấn bản) ≠ addition (sự thêm vào)', '/ɪˈdɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/edi/editi/edition__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-02', 3, 'silver', 'bạc; màu bạc', 'noun', '[{"en":"My grandmother gave me a small ring made of silver.","vi":"Bà tặng tôi một chiếc nhẫn nhỏ làm bằng bạc."},{"en":"He won a silver medal in the swimming race.","vi":"Anh ấy giành huy chương bạc ở cuộc thi bơi."},{"en":"She painted the old door silver to make it look modern.","vi":"Cô ấy sơn cánh cửa cũ màu bạc cho trông hiện đại."}]', '[{"phrase":"silver medal"},{"phrase":"silver ring"},{"phrase":"solid silver"}]', NULL, '/ˈsɪlvər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sil/silve/silver__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-02', 4, 'entertainment', 'sự giải trí; chương trình giải trí', 'noun', '[{"en":"There isn''t much entertainment for young people in this small town.","vi":"Ở thị trấn nhỏ này không có nhiều hoạt động giải trí cho giới trẻ."},{"en":"The hotel offers live entertainment every Friday and Saturday night.","vi":"Khách sạn có chương trình biểu diễn trực tiếp vào mỗi tối thứ Sáu và thứ Bảy."},{"en":"We watched a few old movies for entertainment during the long flight.","vi":"Chúng tôi xem vài bộ phim cũ để giải trí trong chuyến bay dài."}]', '[{"phrase":"live entertainment"},{"phrase":"entertainment industry"},{"phrase":"for entertainment"}]', 'không đếm được', '/ˌentərˈteɪnmənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ent/enter/entertainment__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-02', 5, 'honest', 'trung thực; thẳng thắn', 'adjective', '[{"en":"Please be honest with me and tell me what you really think.","vi":"Hãy thẳng thắn với tôi và cho tôi biết bạn thực sự nghĩ gì."},{"en":"He is an honest man who always pays his debts on time.","vi":"Anh ấy là người trung thực, luôn trả nợ đúng hạn."},{"en":"To be honest, I didn''t enjoy the movie very much.","vi":"Thành thật mà nói, tôi không thích bộ phim đó lắm."}]', '[{"phrase":"be honest with"},{"phrase":"to be honest"},{"phrase":"honest answer"},{"phrase":"honest opinion"}]', 'chữ h câm: an honest man', '/ˈɑːnɪst/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hon/hones/honest__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-02', 6, 'undertake', 'đảm nhận; tiến hành', 'verb', '[{"en":"The city plans to undertake major repairs on the old bridge next year.","vi":"Thành phố dự định tiến hành sửa chữa lớn cây cầu cũ vào năm tới."},{"en":"She undertook the task of organizing the whole event by herself.","vi":"Cô ấy đã tự mình đảm nhận việc tổ chức toàn bộ sự kiện."},{"en":"Few students are willing to undertake such a difficult research project.","vi":"Rất ít sinh viên sẵn sàng thực hiện một dự án nghiên cứu khó như vậy."}]', '[{"phrase":"undertake a task"},{"phrase":"undertake research"},{"phrase":"undertake a project"},{"phrase":"undertake a study"}]', 'undertake – undertook – undertaken', '/ˌʌndərˈteɪk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/und/under/undertake__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-02', 7, 'retail', 'bán lẻ; ngành bán lẻ', 'noun', '[{"en":"My sister has worked in retail for almost ten years.","vi":"Chị tôi đã làm trong ngành bán lẻ gần mười năm."},{"en":"Online shopping has changed the way retail works in small towns.","vi":"Mua sắm trực tuyến đã thay đổi cách ngành bán lẻ vận hành ở các thị trấn nhỏ."},{"en":"The shop sells these jackets at half the normal retail price.","vi":"Cửa hàng bán những chiếc áo khoác này với giá bằng một nửa giá bán lẻ thông thường."}]', '[{"phrase":"retail price"},{"phrase":"retail store"},{"phrase":"work in retail"},{"phrase":"retail sales"}]', 'retail (bán lẻ) ≠ wholesale (bán buôn)', '/ˈriːteɪl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/ret/retai/retail__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-02', 8, 'wire', 'dây điện; dây kim loại', 'noun', '[{"en":"Be careful not to touch that loose wire behind the TV.","vi":"Cẩn thận đừng chạm vào sợi dây điện bị lỏng phía sau tivi."},{"en":"He fixed the broken fence with a piece of wire.","vi":"Anh ấy sửa hàng rào bị hỏng bằng một đoạn dây thép."},{"en":"The electrician replaced all the old wires in our kitchen.","vi":"Thợ điện đã thay toàn bộ dây điện cũ trong bếp nhà tôi."}]', '[{"phrase":"electrical wire"},{"phrase":"copper wire"},{"phrase":"barbed wire"},{"phrase":"loose wire"}]', NULL, '/ˈwaɪər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wir/wire_/wire__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-02', 9, 'unlikely', 'khó xảy ra; không chắc', 'adjective', '[{"en":"It is unlikely to rain today, so leave your umbrella at home.","vi":"Hôm nay khó có mưa, nên cứ để ô ở nhà."},{"en":"She is unlikely to finish the report before Friday.","vi":"Cô ấy khó có thể hoàn thành bản báo cáo trước thứ Sáu."},{"en":"In the unlikely event of a fire, please use the stairs.","vi":"Trong trường hợp hiếm hoi xảy ra hỏa hoạn, vui lòng đi cầu thang bộ."}]', '[{"phrase":"highly unlikely"},{"phrase":"very unlikely"},{"phrase":"unlikely to happen"},{"phrase":"in the unlikely event"}]', 'be unlikely to + V', '/ʌnˈlaɪkli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/unl/unlik/unlikely__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-02', 10, 'gay', 'đồng tính; đồng tính nam', 'adjective', '[{"en":"My brother told our parents that he is gay.","vi":"Anh trai tôi đã nói với bố mẹ rằng anh ấy là người đồng tính."},{"en":"My two uncles are a gay couple who have been together for years.","vi":"Hai chú của tôi là một cặp đồng tính đã bên nhau nhiều năm."},{"en":"Many gay and lesbian students feel welcome at this university.","vi":"Nhiều sinh viên đồng tính nam và nữ cảm thấy được chào đón ở trường đại học này."}]', '[{"phrase":"gay couple"},{"phrase":"gay man"},{"phrase":"gay community"}]', 'Nghĩa cũ ''vui vẻ'' nay rất ít dùng', '/ɡeɪ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gay/gay__/gay__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-02', 11, 'publication', 'sự xuất bản; ấn phẩm', 'noun', '[{"en":"Her first novel will be ready for publication next spring.","vi":"Cuốn tiểu thuyết đầu tay của cô ấy sẽ sẵn sàng xuất bản vào mùa xuân tới."},{"en":"The date of publication is printed on the first page.","vi":"Ngày xuất bản được in ở trang đầu tiên."},{"en":"Our company produces a monthly publication for its customers.","vi":"Công ty chúng tôi phát hành một ấn phẩm hằng tháng cho khách hàng."}]', '[{"phrase":"date of publication"},{"phrase":"publication date"},{"phrase":"monthly publication"},{"phrase":"ready for publication"}]', NULL, '/ˌpʌblɪˈkeɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pub/publi/publication__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-02', 12, 'slight', 'nhẹ; nhỏ, không đáng kể', 'adjective', '[{"en":"I have a slight headache, but I can still go to work.","vi":"Tôi hơi đau đầu, nhưng vẫn đi làm được."},{"en":"There has been a slight change in the plan.","vi":"Kế hoạch có một chút thay đổi."},{"en":"She speaks English with a slight French accent.","vi":"Cô ấy nói tiếng Anh hơi pha giọng Pháp."}]', '[{"phrase":"slight change"},{"phrase":"slight increase"},{"phrase":"slight problem"},{"phrase":"slight accent"}]', 'not the slightest idea: hoàn toàn không biết', '/slaɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sli/sligh/slight__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-02', 13, 'unknown', 'không rõ; không được biết đến', 'adjective', '[{"en":"The cause of the fire is still unknown.","vi":"Nguyên nhân vụ cháy vẫn chưa rõ."},{"en":"The band was completely unknown until their song went viral online.","vi":"Ban nhạc hoàn toàn vô danh cho đến khi bài hát của họ gây sốt trên mạng."},{"en":"For unknown reasons, the train stopped in the middle of nowhere.","vi":"Không rõ vì lý do gì, đoàn tàu dừng lại giữa nơi đồng không mông quạnh."}]', '[{"phrase":"for unknown reasons"},{"phrase":"completely unknown"},{"phrase":"relatively unknown"},{"phrase":"still unknown"}]', NULL, '/ˌʌnˈnəʊn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/unk/unkno/unknown__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-02', 14, 'framework', 'khuôn khổ; bộ khung', 'noun', '[{"en":"The report gives us a clear framework for making decisions.","vi":"Bản báo cáo cho chúng tôi một khuôn khổ rõ ràng để đưa ra quyết định."},{"en":"The workers built a wooden framework before adding the walls.","vi":"Các công nhân dựng một bộ khung gỗ trước khi làm tường."},{"en":"All new rules must work within the existing legal framework.","vi":"Mọi quy định mới phải nằm trong khuôn khổ pháp lý hiện hành."}]', '[{"phrase":"legal framework"},{"phrase":"within the framework of"},{"phrase":"provide a framework"},{"phrase":"basic framework"}]', NULL, '/ˈfreɪmwɜːrk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fra/frame/framework__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-02', 15, 'zone', 'khu vực; vùng', 'noun', '[{"en":"You can''t park here because it''s a no-parking zone.","vi":"Bạn không được đỗ xe ở đây vì đây là khu vực cấm đỗ."},{"en":"My parents live in a different time zone, so calling is hard.","vi":"Bố mẹ tôi sống ở múi giờ khác nên gọi điện khá khó khăn."},{"en":"Drivers must slow down in school zones.","vi":"Tài xế phải giảm tốc độ ở khu vực trường học."}]', '[{"phrase":"time zone"},{"phrase":"school zone"},{"phrase":"no-parking zone"},{"phrase":"comfort zone"}]', 'time zone: múi giờ', '/zəʊn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/z/zon/zone_/zone__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-02', 16, 'restrict', 'hạn chế; giới hạn', 'verb', '[{"en":"The doctor told him to restrict the amount of salt he eats.","vi":"Bác sĩ bảo anh ấy hạn chế lượng muối ăn vào."},{"en":"Parking in this area is restricted to residents only.","vi":"Việc đỗ xe ở khu vực này chỉ giới hạn cho cư dân."},{"en":"Many parents restrict how much time their children spend online.","vi":"Nhiều bố mẹ giới hạn thời gian con cái dùng mạng."}]', '[{"phrase":"restrict access to"},{"phrase":"restrict the use of"},{"phrase":"be restricted to"}]', 'restrict sth to sth', '/rɪˈstrɪkt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/res/restr/restrict__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-02', 17, 'trace', 'dấu vết; một chút', 'noun', '[{"en":"We searched the whole house, but there was no trace of my keys.","vi":"Chúng tôi lục khắp nhà nhưng không thấy tăm hơi chùm chìa khóa của tôi đâu."},{"en":"There were traces of mud on his shoes.","vi":"Có dấu vết bùn trên giày của anh ấy."},{"en":"I could hear a trace of sadness in her voice.","vi":"Tôi nghe thấy một chút buồn bã trong giọng nói của cô ấy."}]', '[{"phrase":"without a trace"},{"phrase":"no trace of"},{"phrase":"leave a trace"}]', 'Động từ trace: lần theo, truy tìm', '/treɪs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tra/trace/trace__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-02', 18, 'inch', 'inch (2,54 cm); một khoảng rất nhỏ', 'noun', '[{"en":"My son has grown two inches since last summer.","vi":"Con trai tôi đã cao thêm hai inch kể từ mùa hè năm ngoái."},{"en":"Cut the cake into small squares, about two inches wide.","vi":"Cắt bánh thành những miếng vuông nhỏ, rộng khoảng hai inch."},{"en":"The car stopped just inches from the little dog.","vi":"Chiếc xe dừng lại chỉ cách chú chó nhỏ trong gang tấc."}]', '[{"phrase":"inch by inch"},{"phrase":"every inch of"},{"phrase":"inches away"}]', '1 inch = 2,54 cm', '/ɪntʃ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inc/inch_/inch__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-02', 19, 'equivalent', 'tương đương', 'adjective', '[{"en":"One cup is roughly equivalent to 240 milliliters.","vi":"Một cốc tương đương khoảng 240 mi-li-lít."},{"en":"Her weekly pay is equivalent to what I earn in a month.","vi":"Tiền lương một tuần của cô ấy tương đương số tiền tôi kiếm được trong một tháng."},{"en":"Is there an equivalent word for this in Vietnamese?","vi":"Trong tiếng Việt có từ nào tương đương với từ này không?"}]', '[{"phrase":"equivalent to"},{"phrase":"roughly equivalent"},{"phrase":"the equivalent of"}]', 'be equivalent to sth', '/ɪˈkwɪvələnt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/equ/equiv/equivalent__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-02', 20, 'solid', 'rắn, đặc; chắc chắn, vững chắc', 'adjective', '[{"en":"Water becomes solid when the temperature drops below zero.","vi":"Nước trở thành thể rắn khi nhiệt độ xuống dưới không độ."},{"en":"This table is made of solid wood, so it will last.","vi":"Chiếc bàn này làm bằng gỗ nguyên khối nên sẽ bền."},{"en":"You need solid evidence before you accuse anyone of lying.","vi":"Bạn cần bằng chứng xác đáng trước khi buộc tội ai đó nói dối."}]', '[{"phrase":"solid wood"},{"phrase":"solid food"},{"phrase":"solid evidence"},{"phrase":"solid foundation"}]', NULL, '/ˈsɑːlɪd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sol/solid/solid__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-02', 21, 'enterprise', 'doanh nghiệp; công việc kinh doanh', 'noun', '[{"en":"The government offers loans to help small enterprises grow.","vi":"Chính phủ cho vay vốn để giúp các doanh nghiệp nhỏ phát triển."},{"en":"Her family runs a successful farming enterprise in the countryside.","vi":"Gia đình cô ấy điều hành một doanh nghiệp nông nghiệp thành công ở nông thôn."},{"en":"Starting a new enterprise always involves some risk.","vi":"Khởi sự một công việc kinh doanh mới luôn có rủi ro nhất định."}]', '[{"phrase":"small enterprise"},{"phrase":"private enterprise"},{"phrase":"state enterprise"}]', NULL, '/ˈentərpraɪz/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ent/enter/enterprise__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-02', 22, 'elderly', 'cao tuổi, lớn tuổi', 'adjective', '[{"en":"He helps his elderly neighbor carry her shopping upstairs.","vi":"Anh ấy giúp bà hàng xóm lớn tuổi mang đồ đi chợ lên lầu."},{"en":"Please give your seat to elderly passengers on the bus.","vi":"Hãy nhường ghế cho hành khách cao tuổi trên xe buýt."},{"en":"The center provides free meals for the elderly in the area.","vi":"Trung tâm cung cấp bữa ăn miễn phí cho người cao tuổi trong khu vực."}]', '[{"phrase":"elderly people"},{"phrase":"elderly parents"},{"phrase":"the elderly"},{"phrase":"elderly relatives"}]', 'the elderly: người cao tuổi; lịch sự hơn old', '/ˈeldərli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eld/elder/elderly__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-02', 23, 'owe', 'nợ; có được là nhờ', 'verb', '[{"en":"I still owe my brother fifty dollars from last month.","vi":"Tôi vẫn còn nợ anh trai năm mươi đô la từ tháng trước."},{"en":"How much do I owe you for the coffee?","vi":"Tôi phải trả bạn bao nhiêu tiền cà phê?"},{"en":"She owes her success to her parents'' support.","vi":"Cô ấy có được thành công là nhờ sự ủng hộ của bố mẹ."}]', '[{"phrase":"owe money"},{"phrase":"owe somebody a favor"},{"phrase":"owe an apology"},{"phrase":"owe something to"}]', 'owe sb sth / owe sth to sb', '/əʊ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/owe/owe__/owe__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-02', 24, 'governor', 'thống đốc; tỉnh trưởng', 'noun', '[{"en":"The governor opened the new hospital on Monday morning.","vi":"Thống đốc đã khánh thành bệnh viện mới vào sáng thứ Hai."},{"en":"The central bank governor announced that interest rates would stay the same.","vi":"Thống đốc ngân hàng trung ương thông báo lãi suất sẽ giữ nguyên."},{"en":"He was elected governor of the state last year.","vi":"Ông ấy được bầu làm thống đốc bang vào năm ngoái."}]', '[{"phrase":"state governor"},{"phrase":"central bank governor"},{"phrase":"provincial governor"}]', NULL, '/ˈɡʌvərnər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gov/gover/governor__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-02', 25, 'uniform', 'đồng phục', 'noun', '[{"en":"All students must wear a uniform to school.","vi":"Tất cả học sinh phải mặc đồng phục đến trường."},{"en":"The nurses changed out of their uniforms after work.","vi":"Các y tá thay đồng phục ra sau giờ làm."},{"en":"He looked very smart in his new police uniform.","vi":"Anh ấy trông rất bảnh bao trong bộ đồng phục cảnh sát mới."}]', '[{"phrase":"school uniform"},{"phrase":"wear a uniform"},{"phrase":"police uniform"},{"phrase":"in uniform"}]', NULL, '/ˈjuːnɪfɔːrm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/uni/unifo/uniform__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-02', 26, 'port', 'cảng; thành phố cảng', 'noun', '[{"en":"The ship will arrive at the port early tomorrow morning.","vi":"Con tàu sẽ cập cảng vào sáng sớm mai."},{"en":"Hai Phong is a busy port in northern Vietnam.","vi":"Hải Phòng là một thành phố cảng sầm uất ở miền Bắc Việt Nam."},{"en":"Our cruise stopped at three small ports along the coast.","vi":"Chuyến du thuyền của chúng tôi dừng ở ba cảng nhỏ dọc bờ biển."}]', '[{"phrase":"busy port"},{"phrase":"fishing port"},{"phrase":"port city"},{"phrase":"arrive in port"}]', 'Cũng có nghĩa: cổng kết nối (USB port)', '/pɔːrt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/por/port_/port__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-02', 27, 'pitch', 'sân (thi đấu); độ cao (âm thanh); lời chào hàng', 'noun', '[{"en":"The players walked onto the pitch as the crowd cheered.","vi":"Các cầu thủ bước ra sân trong tiếng reo hò của khán giả."},{"en":"Her voice rises to a higher pitch when she gets excited.","vi":"Giọng cô ấy cao vút lên mỗi khi phấn khích."},{"en":"He gave a short sales pitch to every customer who walked in.","vi":"Anh ấy chào hàng ngắn gọn với mọi vị khách bước vào."}]', '[{"phrase":"football pitch"},{"phrase":"sales pitch"},{"phrase":"high pitch"},{"phrase":"on the pitch"}]', 'pitch (sân) chủ yếu dùng ở Anh; Mỹ: field', '/pɪtʃ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pit/pitch/pitch__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-02', 28, 'arrival', 'sự đến; người/vật mới đến', 'noun', '[{"en":"Please check in at the front desk on arrival.","vi":"Vui lòng làm thủ tục ở quầy lễ tân khi đến nơi."},{"en":"The flight''s arrival was delayed by two hours because of fog.","vi":"Chuyến bay đến muộn hai tiếng vì sương mù."},{"en":"The whole family was excited about the arrival of the new baby.","vi":"Cả gia đình háo hức chờ đón em bé mới chào đời."}]', '[{"phrase":"on arrival"},{"phrase":"arrival time"},{"phrase":"new arrival"},{"phrase":"arrival of"}]', 'arrive (v) → arrival (n)', '/əˈraɪvl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/arr/arriv/arrival__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-02', 29, 'contemporary', 'đương đại, hiện đại; cùng thời', 'adjective', '[{"en":"The museum has a large collection of contemporary art.","vi":"Bảo tàng có một bộ sưu tập lớn về nghệ thuật đương đại."},{"en":"I prefer contemporary furniture to old-fashioned styles.","vi":"Tôi thích đồ nội thất hiện đại hơn đồ kiểu cổ."},{"en":"The writer''s letters give us a contemporary account of life in the 1800s.","vi":"Những lá thư của nhà văn cho chúng ta lời kể của người cùng thời về cuộc sống thế kỷ 19."}]', '[{"phrase":"contemporary art"},{"phrase":"contemporary music"},{"phrase":"contemporary literature"},{"phrase":"contemporary design"}]', NULL, '/kənˈtempəreri/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcont/xcontemporary__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-02', 30, 'gate', 'cổng; cửa ra máy bay', 'noun', '[{"en":"Please close the gate so the dog doesn''t run out.","vi":"Làm ơn đóng cổng lại để con chó không chạy ra ngoài."},{"en":"Passengers for the flight to Tokyo should go to gate 12.","vi":"Hành khách đi Tokyo vui lòng đến cửa số 12."},{"en":"The children waited for their parents at the school gate.","vi":"Bọn trẻ đợi bố mẹ ở cổng trường."}]', '[{"phrase":"front gate"},{"phrase":"school gate"},{"phrase":"garden gate"},{"phrase":"boarding gate"}]', NULL, '/ɡeɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gat/gate_/gate__us_1.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-5-03', 'ngsl-5', 'Thông dụng 2.001–2.500 · Bộ 3', 'New General Service List, thứ hạng 2.001–2.500', '#3da9fc', 'BookOpen', 3);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-03', 1, 'ease', 'sự dễ dàng; sự thoải mái', 'noun', '[{"en":"She passed her driving test with ease on the first try.","vi":"Cô ấy đã dễ dàng vượt qua bài thi lái xe ngay lần đầu."},{"en":"This phone is popular because of its ease of use.","vi":"Chiếc điện thoại này được ưa chuộng vì dễ sử dụng."},{"en":"I felt at ease as soon as I met her family.","vi":"Tôi cảm thấy thoải mái ngay khi gặp gia đình cô ấy."}]', '[{"phrase":"with ease"},{"phrase":"ease of use"},{"phrase":"at ease"},{"phrase":"feel at ease"}]', NULL, '/iːz/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eas/ease_/ease__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-03', 2, 'beer', 'bia', 'noun', '[{"en":"Would you like a cold beer after work?","vi":"Bạn có muốn uống một cốc bia lạnh sau giờ làm không?"},{"en":"My father has a glass of beer with dinner on Fridays.","vi":"Bố tôi uống một cốc bia trong bữa tối vào các thứ Sáu."},{"en":"They ordered two beers and a plate of fries.","vi":"Họ gọi hai cốc bia và một đĩa khoai tây chiên."}]', '[{"phrase":"cold beer"},{"phrase":"a glass of beer"},{"phrase":"drink beer"},{"phrase":"a bottle of beer"}]', NULL, '/bɪr/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bee/beer_/beer__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-03', 3, 'specialist', 'chuyên gia; bác sĩ chuyên khoa', 'noun', '[{"en":"My doctor sent me to a heart specialist for more tests.","vi":"Bác sĩ chuyển tôi đến một bác sĩ chuyên khoa tim để làm thêm xét nghiệm."},{"en":"She works as a computer specialist at a large bank.","vi":"Cô ấy làm chuyên gia máy tính tại một ngân hàng lớn."},{"en":"We asked a specialist to check the old roof.","vi":"Chúng tôi đã nhờ một chuyên gia kiểm tra mái nhà cũ."}]', '[{"phrase":"see a specialist"},{"phrase":"heart specialist"},{"phrase":"medical specialist"}]', NULL, '/ˈspeʃəlɪst/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/spe/speci/specialist__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-03', 4, 'assure', 'cam đoan; đảm bảo (với ai)', 'verb', '[{"en":"I can assure you that your bag will be safe here.","vi":"Tôi có thể cam đoan với bạn rằng túi của bạn để ở đây sẽ an toàn."},{"en":"The doctor assured us that the surgery went well.","vi":"Bác sĩ đảm bảo với chúng tôi rằng ca phẫu thuật đã diễn ra tốt đẹp."},{"en":"She assured her parents that she would call every week.","vi":"Cô ấy cam đoan với bố mẹ rằng sẽ gọi điện về mỗi tuần."}]', '[{"phrase":"I can assure you"},{"phrase":"assure somebody that"},{"phrase":"rest assured"}]', 'assure (cam đoan với ai) ≠ ensure (đảm bảo việc gì xảy ra)', '/əˈʃʊr/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ass/assur/assure__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-03', 5, 'profile', 'hồ sơ; trang cá nhân; mặt nghiêng', 'noun', '[{"en":"Please update your profile with your new phone number.","vi":"Vui lòng cập nhật số điện thoại mới vào trang cá nhân của bạn."},{"en":"The company keeps a detailed profile of each customer.","vi":"Công ty lưu một hồ sơ chi tiết về từng khách hàng."},{"en":"The photo shows the old man''s face in profile.","vi":"Bức ảnh chụp nghiêng khuôn mặt của ông lão."}]', '[{"phrase":"update your profile"},{"phrase":"profile picture"},{"phrase":"in profile"}]', NULL, '/ˈprəʊfaɪl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/profi/profile__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-03', 6, 'mood', 'tâm trạng; không khí', 'noun', '[{"en":"I''m not in the mood to cook tonight.","vi":"Tối nay tôi không có tâm trạng nấu ăn."},{"en":"She was in a good mood after the long weekend.","vi":"Cô ấy có tâm trạng tốt sau kỳ nghỉ cuối tuần dài."},{"en":"The mood at the party changed when the music stopped.","vi":"Không khí bữa tiệc thay đổi khi nhạc tắt."}]', '[{"phrase":"in a good mood"},{"phrase":"in a bad mood"},{"phrase":"in the mood for"}]', NULL, '/muːd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/moo/mood_/mood__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-03', 7, 'episode', 'tập (phim); giai đoạn, sự việc', 'noun', '[{"en":"We watched three episodes of the show last night.","vi":"Tối qua chúng tôi đã xem ba tập của chương trình đó."},{"en":"I missed the final episode, so please don''t tell me the ending.","vi":"Tôi đã bỏ lỡ tập cuối, nên đừng kể cho tôi đoạn kết nhé."},{"en":"He doesn''t like to talk about that difficult episode in his life.","vi":"Anh ấy không thích nhắc đến giai đoạn khó khăn đó trong đời mình."}]', '[{"phrase":"final episode"},{"phrase":"latest episode"},{"phrase":"next episode"}]', NULL, '/ˈepɪsəʊd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/epi/episo/episode__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-03', 8, 'crack', 'nứt; làm nứt; đập (trứng)', 'verb', '[{"en":"The glass cracked when I poured hot water into it.","vi":"Chiếc cốc bị nứt khi tôi rót nước nóng vào."},{"en":"Crack two eggs into a bowl and mix them well.","vi":"Đập hai quả trứng vào bát rồi trộn đều."},{"en":"He fell off his bike and cracked a bone in his arm.","vi":"Anh ấy ngã xe đạp và bị rạn xương tay."}]', '[{"phrase":"crack an egg"},{"phrase":"crack a joke"},{"phrase":"crack open"}]', NULL, '/kræk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cra/crack/crack__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-03', 9, 'numerous', 'nhiều; vô số', 'adjective', '[{"en":"I have called the company numerous times this week.","vi":"Tuần này tôi đã gọi cho công ty rất nhiều lần."},{"en":"The city has numerous parks where families can relax.","vi":"Thành phố có rất nhiều công viên để các gia đình thư giãn."},{"en":"She has won numerous awards for her children''s books.","vi":"Cô ấy đã giành được vô số giải thưởng cho sách thiếu nhi của mình."}]', '[{"phrase":"numerous times"},{"phrase":"on numerous occasions"},{"phrase":"numerous examples"}]', NULL, '/ˈnuːmərəs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/num/numer/numerous__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-03', 10, 'submit', 'nộp; đệ trình', 'verb', '[{"en":"Please submit your homework by Friday morning.","vi":"Vui lòng nộp bài tập về nhà trước sáng thứ Sáu."},{"en":"I need to submit an application for the job by Monday.","vi":"Tôi cần nộp đơn xin công việc đó trước thứ Hai."},{"en":"All reports must be submitted to the manager before the meeting.","vi":"Tất cả báo cáo phải được nộp cho quản lý trước cuộc họp."}]', '[{"phrase":"submit an application"},{"phrase":"submit a report"},{"phrase":"submit a proposal"}]', NULL, '/səbˈmɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sub/submi/submit__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-03', 11, 'symptom', 'triệu chứng; dấu hiệu', 'noun', '[{"en":"Fever and a sore throat are common symptoms of the flu.","vi":"Sốt và đau họng là những triệu chứng thường gặp của bệnh cúm."},{"en":"Call your doctor if the symptoms get worse.","vi":"Hãy gọi cho bác sĩ nếu các triệu chứng nặng hơn."},{"en":"Feeling tired all the time can be a symptom of stress.","vi":"Lúc nào cũng thấy mệt mỏi có thể là dấu hiệu của căng thẳng."}]', '[{"phrase":"common symptoms"},{"phrase":"mild symptoms"},{"phrase":"symptoms get worse"}]', NULL, '/ˈsɪmptəm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sym/sympt/symptom__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-03', 12, 'virtually', 'hầu như; gần như', 'adverb', '[{"en":"Virtually everyone in my class has a smartphone.","vi":"Hầu như ai trong lớp tôi cũng có điện thoại thông minh."},{"en":"It is virtually impossible to find a parking space here.","vi":"Gần như không thể tìm được chỗ đậu xe ở đây."},{"en":"The town was virtually empty during the holiday.","vi":"Thị trấn gần như vắng tanh trong kỳ nghỉ lễ."}]', '[{"phrase":"virtually impossible"},{"phrase":"virtually everyone"},{"phrase":"virtually all"}]', NULL, '/ˈvɜːrtʃuəli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/vir/virtu/virtually__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-03', 13, 'era', 'kỷ nguyên; thời đại', 'noun', '[{"en":"In the digital era, people rarely write letters by hand.","vi":"Trong thời đại kỹ thuật số, người ta hiếm khi viết thư tay."},{"en":"My grandparents grew up in an era without television.","vi":"Ông bà tôi lớn lên trong một thời đại chưa có tivi."},{"en":"The internet started a new era in the way people communicate.","vi":"Internet đã mở ra một kỷ nguyên mới trong cách con người giao tiếp."}]', '[{"phrase":"a new era"},{"phrase":"the digital era"},{"phrase":"the end of an era"}]', NULL, '/ˈɪrə/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/era/era__/era__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-03', 14, 'coverage', 'việc đưa tin; vùng phủ sóng; phạm vi bảo hiểm', 'noun', '[{"en":"The news coverage of the storm lasted all evening.","vi":"Việc đưa tin về cơn bão kéo dài suốt buổi tối."},{"en":"Our phone company has poor coverage in the mountains.","vi":"Nhà mạng của chúng tôi phủ sóng kém ở vùng núi."},{"en":"Does your health insurance include coverage for dental care?","vi":"Bảo hiểm y tế của bạn có chi trả cho việc chăm sóc răng không?"}]', '[{"phrase":"news coverage"},{"phrase":"media coverage"},{"phrase":"live coverage"},{"phrase":"insurance coverage"}]', 'không đếm được', '/ˈkʌvərɪdʒ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cov/cover/coverage__us_2_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-03', 15, 'tension', 'sự căng thẳng; độ căng', 'noun', '[{"en":"You could feel the tension in the room during the meeting.","vi":"Bạn có thể cảm nhận sự căng thẳng trong phòng suốt cuộc họp."},{"en":"A hot bath helps reduce the tension in my shoulders.","vi":"Tắm nước nóng giúp giảm độ căng cứng ở vai tôi."},{"en":"There is some tension between the two brothers these days.","vi":"Dạo này giữa hai anh em có chút căng thẳng."}]', '[{"phrase":"tension between"},{"phrase":"reduce tension"},{"phrase":"muscle tension"}]', NULL, '/ˈtenʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/ten/tensi/tension__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-03', 16, 'cable', 'dây cáp; truyền hình cáp', 'noun', '[{"en":"I need a longer charging cable for my phone.","vi":"Tôi cần một sợi cáp sạc dài hơn cho điện thoại."},{"en":"Can you plug this cable into the back of the TV?","vi":"Bạn cắm sợi cáp này vào phía sau tivi giúp tôi được không?"},{"en":"We stopped paying for cable because we watch everything online.","vi":"Chúng tôi ngừng trả tiền truyền hình cáp vì xem mọi thứ trên mạng."}]', '[{"phrase":"charging cable"},{"phrase":"power cable"},{"phrase":"cable TV"}]', NULL, '/ˈkeɪbl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cab/cable/cable__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-03', 17, 'sensitive', 'nhạy cảm; dễ bị tổn thương', 'adjective', '[{"en":"My teeth are sensitive to cold drinks.","vi":"Răng tôi nhạy cảm với đồ uống lạnh."},{"en":"He is very sensitive, so be careful what you say.","vi":"Anh ấy rất dễ bị tổn thương, nên hãy cẩn thận khi nói."},{"en":"Money is a sensitive topic in many families.","vi":"Tiền bạc là một chủ đề nhạy cảm trong nhiều gia đình."}]', '[{"phrase":"sensitive skin"},{"phrase":"sensitive to"},{"phrase":"sensitive topic"},{"phrase":"sensitive issue"}]', NULL, '/ˈsensətɪv/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sen/sensi/sensitive__us_4.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-03', 18, 'nervous', 'lo lắng; hồi hộp', 'adjective', '[{"en":"I always feel nervous before a job interview.","vi":"Tôi luôn cảm thấy hồi hộp trước buổi phỏng vấn xin việc."},{"en":"She was too nervous to speak in front of the class.","vi":"Cô ấy quá lo lắng nên không dám nói trước lớp."},{"en":"Driving on busy roads makes my mother nervous.","vi":"Lái xe trên những con đường đông đúc khiến mẹ tôi lo lắng."}]', '[{"phrase":"feel nervous"},{"phrase":"nervous about"},{"phrase":"get nervous"}]', NULL, '/ˈnɜːrvəs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/ner/nervo/nervous__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-03', 19, 'input', 'ý kiến đóng góp; dữ liệu đầu vào', 'noun', '[{"en":"Thanks for your input on the new website design.","vi":"Cảm ơn ý kiến đóng góp của bạn về thiết kế trang web mới."},{"en":"We want some input from parents before we change the school rules.","vi":"Chúng tôi muốn nghe một số ý kiến từ phụ huynh trước khi thay đổi nội quy trường."},{"en":"The program checks the user''s input before saving it.","vi":"Chương trình kiểm tra dữ liệu người dùng nhập vào trước khi lưu."}]', '[{"phrase":"input from"},{"phrase":"valuable input"},{"phrase":"user input"}]', NULL, '/ˈɪnpʊt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inp/input/input__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-03', 20, 'isolate', 'cô lập; cách ly', 'verb', '[{"en":"Doctors isolated the sick child to protect the other patients.","vi":"Các bác sĩ đã cách ly đứa trẻ bị bệnh để bảo vệ những bệnh nhân khác."},{"en":"The heavy snow isolated the village for a week.","vi":"Tuyết rơi dày đã cô lập ngôi làng suốt một tuần."},{"en":"Working from home can make some people feel isolated.","vi":"Làm việc ở nhà có thể khiến một số người cảm thấy bị cô lập."}]', '[{"phrase":"feel isolated"},{"phrase":"socially isolated"},{"phrase":"isolate from"}]', NULL, '/ˈaɪsəleɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/iso/isola/isolate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-03', 21, 'prisoner', 'tù nhân', 'noun', '[{"en":"The prisoner was released after ten years in jail.","vi":"Người tù được thả sau mười năm ngồi tù."},{"en":"Visitors can only see prisoners on Sunday afternoons.","vi":"Khách thăm chỉ được gặp tù nhân vào chiều Chủ nhật."},{"en":"Police are still looking for the two prisoners who escaped.","vi":"Cảnh sát vẫn đang truy tìm hai tù nhân đã vượt ngục."}]', '[{"phrase":"release a prisoner"},{"phrase":"escaped prisoner"},{"phrase":"prisoner of war"}]', NULL, '/ˈprɪznər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pri/priso/prisoner__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-03', 22, 'eliminate', 'loại bỏ; loại (khỏi cuộc thi)', 'verb', '[{"en":"Good planning can eliminate the need for extra meetings.","vi":"Lên kế hoạch tốt có thể giúp không cần đến những cuộc họp thêm."},{"en":"Our team was eliminated in the first round of the tournament.","vi":"Đội chúng tôi đã bị loại ngay vòng đầu của giải đấu."},{"en":"Try to eliminate sugar from your diet for a month.","vi":"Hãy thử loại bỏ đường khỏi chế độ ăn của bạn trong một tháng."}]', '[{"phrase":"eliminate the need"},{"phrase":"completely eliminate"},{"phrase":"be eliminated from"}]', NULL, '/ɪˈlɪmɪneɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eli/elimi/eliminate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-03', 23, 'tight', 'chật; chặt; eo hẹp', 'adjective', '[{"en":"These jeans feel too tight after the holidays.","vi":"Chiếc quần jean này mặc thấy chật quá sau kỳ nghỉ lễ."},{"en":"Make sure the lid is tight before you shake the bottle.","vi":"Hãy chắc chắn nắp đã được đậy chặt trước khi lắc chai."},{"en":"Money is tight, so we''re not going on vacation this year.","vi":"Tiền bạc eo hẹp nên năm nay chúng tôi sẽ không đi du lịch."}]', '[{"phrase":"too tight"},{"phrase":"tight schedule"},{"phrase":"tight budget"},{"phrase":"money is tight"}]', NULL, '/taɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tig/tight/tight__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-03', 24, 'wet', 'ướt; có mưa', 'adjective', '[{"en":"Take off your wet shoes before you come inside.","vi":"Hãy cởi đôi giày ướt ra trước khi vào nhà."},{"en":"We all got wet because we forgot our umbrellas.","vi":"Tất cả chúng tôi đều bị ướt vì quên mang ô."},{"en":"It was a cold and wet day, so we stayed home.","vi":"Hôm đó trời lạnh và mưa nên chúng tôi ở nhà."}]', '[{"phrase":"get wet"},{"phrase":"wet weather"},{"phrase":"soaking wet"}]', NULL, '/wet/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wet/wet__/wet__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-03', 25, 'secondary', 'thứ yếu; (thuộc) trung học', 'adjective', '[{"en":"For me, the salary is secondary to the people I work with.","vi":"Với tôi, mức lương là thứ yếu so với những người làm việc cùng mình."},{"en":"My sister teaches math at a secondary school.","vi":"Chị tôi dạy toán ở một trường trung học."},{"en":"Price was a secondary concern when we chose the hotel.","vi":"Giá cả chỉ là mối quan tâm thứ yếu khi chúng tôi chọn khách sạn."}]', '[{"phrase":"secondary school"},{"phrase":"secondary education"},{"phrase":"secondary to"}]', NULL, '/ˈsekənderi/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sec/secon/secondary__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-03', 26, 'welfare', 'phúc lợi; sự khỏe mạnh và an toàn', 'noun', '[{"en":"Our manager really cares about staff welfare.","vi":"Quản lý của chúng tôi thực sự quan tâm đến phúc lợi của nhân viên."},{"en":"Animal welfare groups found new homes for the dogs.","vi":"Các tổ chức bảo vệ quyền lợi động vật đã tìm nhà mới cho những chú chó."},{"en":"Parents are responsible for the welfare of their children.","vi":"Cha mẹ có trách nhiệm chăm lo sức khỏe và sự an toàn của con cái."}]', '[{"phrase":"animal welfare"},{"phrase":"child welfare"},{"phrase":"staff welfare"},{"phrase":"social welfare"}]', 'không đếm được', '/ˈwelfer/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wel/welfa/welfare__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-03', 27, 'recruit', 'tuyển; tuyển dụng', 'verb', '[{"en":"The company plans to recruit fifty new workers this year.","vi":"Công ty dự định tuyển năm mươi công nhân mới trong năm nay."},{"en":"We need to recruit volunteers for the school fair.","vi":"Chúng tôi cần tuyển tình nguyện viên cho hội chợ của trường."},{"en":"She was recruited by a large bank straight after university.","vi":"Cô ấy được một ngân hàng lớn tuyển dụng ngay khi vừa tốt nghiệp đại học."}]', '[{"phrase":"recruit staff"},{"phrase":"recruit volunteers"},{"phrase":"recruit new members"}]', NULL, '/rɪˈkruːt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rec/recru/recruit__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-03', 28, 'exclude', 'loại trừ; không bao gồm; không cho tham gia', 'verb', '[{"en":"The price of the tour excludes meals and drinks.","vi":"Giá tour không bao gồm đồ ăn và thức uống."},{"en":"The other kids excluded him from their games.","vi":"Những đứa trẻ khác không cho cậu ấy chơi cùng."},{"en":"We can''t exclude the possibility that the flight will be late.","vi":"Chúng ta không thể loại trừ khả năng chuyến bay sẽ bị trễ."}]', '[{"phrase":"exclude from"},{"phrase":"exclude the possibility"},{"phrase":"feel excluded"}]', NULL, '/ɪkˈskluːd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exc/exclu/exclude__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-03', 29, 'string', 'dây; dây đàn; chuỗi', 'noun', '[{"en":"She tied the box with a piece of string.","vi":"Cô ấy buộc chiếc hộp bằng một sợi dây."},{"en":"One of the strings on my guitar broke last night.","vi":"Tối qua một dây đàn guitar của tôi bị đứt."},{"en":"Our team had a string of wins this season.","vi":"Mùa giải này đội chúng tôi đã có một chuỗi trận thắng."}]', '[{"phrase":"a piece of string"},{"phrase":"guitar string"},{"phrase":"a string of"}]', 'Nghĩa "dây buộc" không đếm được: a piece of string', '/strɪŋ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/str/strin/string__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-03', 30, 'cloud', 'mây; đám (khói, bụi)', 'noun', '[{"en":"There wasn''t a cloud in the sky all day.","vi":"Cả ngày trên trời không có một gợn mây."},{"en":"Dark clouds are coming, so bring your umbrella.","vi":"Mây đen đang kéo đến, nên hãy mang theo ô."},{"en":"A cloud of dust rose behind the truck.","vi":"Một đám bụi bốc lên phía sau chiếc xe tải."}]', '[{"phrase":"dark clouds"},{"phrase":"a cloud of dust"},{"phrase":"a cloud of smoke"}]', NULL, '/klaʊd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/clo/cloud/cloud__us_1.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-5-04', 'ngsl-5', 'Thông dụng 2.001–2.500 · Bộ 4', 'New General Service List, thứ hạng 2.001–2.500', '#3da9fc', 'BookOpen', 4);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-04', 1, 'persuade', 'thuyết phục', 'verb', '[{"en":"She finally persuaded her parents to let her study abroad.","vi":"Cuối cùng cô ấy đã thuyết phục được bố mẹ cho mình đi du học."},{"en":"I tried to persuade him to stay, but he left anyway.","vi":"Tôi đã cố thuyết phục anh ấy ở lại, nhưng anh ấy vẫn đi."},{"en":"It took a long time to persuade my boss that the plan would work.","vi":"Phải mất rất lâu tôi mới thuyết phục được sếp rằng kế hoạch sẽ thành công."}]', '[{"phrase":"try to persuade"},{"phrase":"persuade someone to do something"},{"phrase":"finally persuade"}]', 'persuade sb to do sth', '/pərˈsweɪd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/per/persu/persuade__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-04', 2, 'inspire', 'truyền cảm hứng; khơi dậy', 'verb', '[{"en":"Her story inspired me to start running again.","vi":"Câu chuyện của cô ấy đã truyền cảm hứng cho tôi bắt đầu chạy bộ trở lại."},{"en":"A good teacher can inspire students to love learning.","vi":"Một giáo viên giỏi có thể truyền cảm hứng để học sinh yêu thích việc học."},{"en":"His calm words inspired confidence in the whole team.","vi":"Những lời nói điềm tĩnh của anh ấy đã khơi dậy niềm tin trong cả đội."}]', '[{"phrase":"inspire confidence"},{"phrase":"inspired by"},{"phrase":"inspire someone to do something"}]', NULL, '/ɪnˈspaɪər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ins/inspi/inspire__us_4.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-04', 3, 'grand', 'lộng lẫy, tráng lệ; lớn lao', 'adjective', '[{"en":"They stayed in a grand old hotel near the river.","vi":"Họ ở trong một khách sạn cổ tráng lệ gần bờ sông."},{"en":"The wedding was held in a grand hall with huge windows.","vi":"Đám cưới được tổ chức trong một hội trường lộng lẫy với những ô cửa sổ lớn."},{"en":"He has grand plans to open his own restaurant one day.","vi":"Anh ấy có kế hoạch lớn là một ngày nào đó sẽ mở nhà hàng riêng."}]', '[{"phrase":"grand hotel"},{"phrase":"grand plans"},{"phrase":"grand opening"}]', NULL, '/ɡrænd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gra/grand/grand__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-04', 4, 'hence', 'vì vậy, do đó', 'adverb', '[{"en":"The roads were icy this morning, hence the long delays.","vi":"Sáng nay đường đóng băng, vì vậy mới bị chậm trễ lâu như thế."},{"en":"The flights were cheap and hence very popular with students.","vi":"Các chuyến bay rẻ, do đó rất được sinh viên ưa chuộng."},{"en":"The shop is right next to the station, and hence always busy.","vi":"Cửa hàng nằm ngay cạnh nhà ga, do đó lúc nào cũng đông khách."}]', '[{"phrase":"and hence"},{"phrase":"hence the name"},{"phrase":"hence the need"}]', 'Trang trọng, thường dùng trong văn viết', '/hens/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hen/hence/hence__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-04', 5, 'crew', 'phi hành đoàn, thủy thủ đoàn; đội, nhóm (làm việc)', 'noun', '[{"en":"The flight crew asked everyone to fasten their seat belts.","vi":"Phi hành đoàn yêu cầu mọi người thắt dây an toàn."},{"en":"The fishing boat had a crew of twelve men.","vi":"Chiếc thuyền đánh cá có thủy thủ đoàn gồm mười hai người."},{"en":"A film crew was working on our street all day.","vi":"Một đoàn làm phim đã làm việc trên phố nhà tôi cả ngày."}]', '[{"phrase":"flight crew"},{"phrase":"film crew"},{"phrase":"crew member"},{"phrase":"cabin crew"}]', NULL, '/kruː/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cre/crew_/crew__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-04', 6, 'phenomenon', 'hiện tượng', 'noun', '[{"en":"Snow in this part of the country is a rare phenomenon.","vi":"Tuyết ở vùng này của đất nước là một hiện tượng hiếm gặp."},{"en":"Working from home has become a common phenomenon in recent years.","vi":"Làm việc tại nhà đã trở thành một hiện tượng phổ biến trong những năm gần đây."},{"en":"Scientists are still trying to explain this strange natural phenomenon.","vi":"Các nhà khoa học vẫn đang cố giải thích hiện tượng tự nhiên kỳ lạ này."}]', '[{"phrase":"natural phenomenon"},{"phrase":"rare phenomenon"},{"phrase":"common phenomenon"},{"phrase":"social phenomenon"}]', 'Số nhiều: phenomena', '/fəˈnɑːmɪnən/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/phe/pheno/phenomenon__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-04', 7, 'pupil', 'học sinh; con ngươi', 'noun', '[{"en":"Our village school has about two hundred pupils.","vi":"Trường làng chúng tôi có khoảng hai trăm học sinh."},{"en":"Each pupil must bring a packed lunch on Friday.","vi":"Mỗi học sinh phải mang theo cơm trưa vào thứ Sáu."},{"en":"In bright light, the pupils of your eyes get smaller.","vi":"Dưới ánh sáng mạnh, con ngươi của mắt sẽ nhỏ lại."}]', '[{"phrase":"primary school pupil"},{"phrase":"former pupil"},{"phrase":"pupils and teachers"}]', 'Hay dùng trong tiếng Anh-Anh; tiếng Mỹ thường dùng student', '/ˈpjuːpl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pup/pupil/pupil__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-04', 8, 'false', 'sai; giả, không thật', 'adjective', '[{"en":"Decide whether each of these sentences is true or false.","vi":"Hãy xác định mỗi câu sau đây là đúng hay sai."},{"en":"He gave the police a false name and address.","vi":"Anh ta khai tên và địa chỉ giả với cảnh sát."},{"en":"The doctor didn''t want to give the family false hope.","vi":"Bác sĩ không muốn mang lại hy vọng hão huyền cho gia đình."}]', '[{"phrase":"true or false"},{"phrase":"false name"},{"phrase":"false hope"},{"phrase":"false alarm"}]', NULL, '/fɔːls/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fal/false/false__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-04', 9, 'assist', 'hỗ trợ, giúp đỡ', 'verb', '[{"en":"Two nurses assisted the doctor during the operation.","vi":"Hai y tá đã hỗ trợ bác sĩ trong ca phẫu thuật."},{"en":"Our staff will be happy to assist you with your luggage.","vi":"Nhân viên của chúng tôi rất sẵn lòng giúp bạn mang hành lý."},{"en":"She was hired to assist the manager with daily tasks.","vi":"Cô ấy được tuyển để hỗ trợ quản lý trong các công việc hằng ngày."}]', '[{"phrase":"assist with"},{"phrase":"assist in"},{"phrase":"assist someone"}]', 'assist sb with/in sth', '/əˈsɪst/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ass/assis/assist__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-04', 10, 'restore', 'khôi phục; phục hồi, trùng tu', 'verb', '[{"en":"It took three hours to restore power after the storm.","vi":"Phải mất ba tiếng mới khôi phục được điện sau cơn bão."},{"en":"They spent two years restoring the old farmhouse.","vi":"Họ đã mất hai năm để trùng tu ngôi nhà trang trại cũ."},{"en":"The new manager helped restore trust between staff and customers.","vi":"Người quản lý mới đã giúp khôi phục lòng tin giữa nhân viên và khách hàng."}]', '[{"phrase":"restore power"},{"phrase":"restore trust"},{"phrase":"restore order"},{"phrase":"fully restored"}]', NULL, '/rɪˈstɔːr/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/res/resto/restore__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-04', 11, 'formula', 'công thức; sữa công thức', 'noun', '[{"en":"Can you remember the formula for the area of a circle?","vi":"Bạn có nhớ công thức tính diện tích hình tròn không?"},{"en":"There is no simple formula for a happy marriage.","vi":"Không có công thức đơn giản nào cho một cuộc hôn nhân hạnh phúc."},{"en":"She mixed the baby''s formula with warm water.","vi":"Cô ấy pha sữa công thức cho em bé bằng nước ấm."}]', '[{"phrase":"mathematical formula"},{"phrase":"a formula for"},{"phrase":"simple formula"},{"phrase":"baby formula"}]', 'Số nhiều: formulas hoặc formulae', '/ˈfɔːrmjələ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/for/formu/formula__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-04', 12, 'alter', 'thay đổi; sửa (quần áo)', 'verb', '[{"en":"We had to alter our travel plans because of the rain.","vi":"Chúng tôi phải thay đổi kế hoạch du lịch vì trời mưa."},{"en":"Moving to the city completely altered her way of life.","vi":"Việc chuyển lên thành phố đã thay đổi hoàn toàn lối sống của cô ấy."},{"en":"I need to have these trousers altered before the wedding.","vi":"Tôi cần mang chiếc quần này đi sửa trước đám cưới."}]', '[{"phrase":"alter plans"},{"phrase":"completely alter"},{"phrase":"significantly alter"}]', 'alter (thay đổi) ≠ altar (bàn thờ)', '/ˈɔːltər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/alt/alter/alter__us_4.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-04', 13, 'perceive', 'nhìn nhận, coi là; nhận thấy', 'verb', '[{"en":"Many people perceive him as shy, but he''s actually very friendly.","vi":"Nhiều người coi anh ấy là người nhút nhát, nhưng thực ra anh ấy rất thân thiện."},{"en":"How is our company perceived by young customers?","vi":"Công ty chúng ta được khách hàng trẻ nhìn nhận như thế nào?"},{"en":"Children often perceive small changes that adults don''t notice.","vi":"Trẻ em thường nhận thấy những thay đổi nhỏ mà người lớn không để ý."}]', '[{"phrase":"perceive something as"},{"phrase":"widely perceived"},{"phrase":"perceive a change"}]', 'perceive sb/sth as ...', '/pərˈsiːv/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/per/perce/perceive__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-04', 14, 'routine', 'thói quen hằng ngày; nếp sinh hoạt', 'noun', '[{"en":"Exercise is an important part of my morning routine.","vi":"Tập thể dục là một phần quan trọng trong thói quen buổi sáng của tôi."},{"en":"Having a new baby completely changed our daily routine.","vi":"Có thêm em bé đã thay đổi hoàn toàn nếp sinh hoạt hằng ngày của chúng tôi."},{"en":"I''m tired of doing the same boring routine every week.","vi":"Tôi chán phải lặp lại những việc nhàm chán y như nhau mỗi tuần."}]', '[{"phrase":"daily routine"},{"phrase":"morning routine"},{"phrase":"normal routine"}]', NULL, '/ruːˈtiːn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rou/routi/routine__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-04', 15, 'sink', 'chìm; lún xuống; (mặt trời) lặn', 'verb', '[{"en":"The small boat hit a rock and sank within minutes.","vi":"Chiếc thuyền nhỏ đâm vào đá và chìm chỉ trong vài phút."},{"en":"My feet sank into the soft, wet sand.","vi":"Chân tôi lún xuống lớp cát ướt và mềm."},{"en":"The sun was sinking behind the hills when we got home.","vi":"Mặt trời đang lặn dần sau những ngọn đồi khi chúng tôi về đến nhà."}]', '[{"phrase":"sink to the bottom"},{"phrase":"sink into"},{"phrase":"slowly sink"}]', 'sink – sank – sunk', '/sɪŋk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sin/sink_/sink__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-04', 16, 'stare', 'nhìn chằm chằm', 'verb', '[{"en":"Why is that man over there staring at us?","vi":"Sao người đàn ông đằng kia cứ nhìn chằm chằm vào chúng ta vậy?"},{"en":"She stared out of the window, lost in thought.","vi":"Cô ấy nhìn đăm đăm ra ngoài cửa sổ, chìm trong suy nghĩ."},{"en":"It''s rude to stare at people on the bus.","vi":"Nhìn chằm chằm người khác trên xe buýt là bất lịch sự."}]', '[{"phrase":"stare at"},{"phrase":"stare out of the window"},{"phrase":"stare into space"}]', 'stare at sb/sth', '/ster/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sta/stare/stare__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-04', 17, 'anymore', 'nữa (không … nữa)', 'adverb', '[{"en":"I don''t live in that apartment anymore.","vi":"Tôi không còn sống ở căn hộ đó nữa."},{"en":"My kids don''t want to watch cartoons anymore.","vi":"Bọn trẻ nhà tôi không muốn xem phim hoạt hình nữa."},{"en":"We can''t afford to eat out every weekend anymore.","vi":"Chúng tôi không còn đủ tiền đi ăn ngoài mỗi cuối tuần nữa."}]', '[{"phrase":"not anymore"},{"phrase":"don''t care anymore"},{"phrase":"not ... anymore"}]', 'Dùng trong câu phủ định/nghi vấn; Anh: any more · Mỹ: anymore', '/ˌɛniːˈmɔr/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-04', 18, 'hero', 'anh hùng, người hùng; nhân vật chính', 'noun', '[{"en":"The firefighter became a local hero after saving the child.","vi":"Người lính cứu hỏa trở thành người hùng của địa phương sau khi cứu đứa bé."},{"en":"My father has always been my hero.","vi":"Bố luôn là người hùng của tôi."},{"en":"The hero of the story is a young farmer.","vi":"Nhân vật chính của câu chuyện là một chàng nông dân trẻ."}]', '[{"phrase":"national hero"},{"phrase":"local hero"},{"phrase":"true hero"}]', 'Số nhiều: heroes', '/ˈhɪrəʊ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/her/hero_/hero__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-04', 19, 'supporter', 'người ủng hộ; cổ động viên', 'noun', '[{"en":"Thousands of supporters came to watch the final match.","vi":"Hàng nghìn cổ động viên đã đến xem trận chung kết."},{"en":"My wife has always been my biggest supporter.","vi":"Vợ tôi luôn là người ủng hộ tôi nhiều nhất."},{"en":"Supporters of the new park say it will help local families.","vi":"Những người ủng hộ công viên mới cho rằng nó sẽ giúp ích cho các gia đình trong vùng."}]', '[{"phrase":"strong supporter"},{"phrase":"biggest supporter"},{"phrase":"loyal supporter"},{"phrase":"football supporter"}]', NULL, '/səˈpɔːrtər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sup/suppo/supporter__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-04', 20, 'convert', 'chuyển đổi, quy đổi; cải tạo', 'verb', '[{"en":"They converted the garage into a small office.","vi":"Họ đã cải tạo nhà để xe thành một văn phòng nhỏ."},{"en":"Can you convert these prices from dollars to euros?","vi":"Bạn có thể quy đổi các mức giá này từ đô la sang euro không?"},{"en":"Solar panels convert sunlight into electricity for the whole building.","vi":"Các tấm pin mặt trời chuyển ánh sáng mặt trời thành điện cho cả tòa nhà."}]', '[{"phrase":"convert into"},{"phrase":"convert to"},{"phrase":"convert a file"}]', 'convert sth into/to sth', '/kənˈvɜːrt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xconv/xconvert__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-04', 21, 'steady', 'đều đặn, ổn định; vững', 'adjective', '[{"en":"Prices have seen a steady rise over the past year.","vi":"Giá cả đã tăng đều đặn trong năm qua."},{"en":"She has a steady job with a good salary.","vi":"Cô ấy có một công việc ổn định với mức lương tốt."},{"en":"Hold the ladder steady while I climb up.","vi":"Giữ thang cho vững trong khi tôi trèo lên."}]', '[{"phrase":"steady job"},{"phrase":"steady rise"},{"phrase":"steady pace"},{"phrase":"steady growth"}]', NULL, '/ˈstedi/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/ste/stead/steady__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-04', 22, 'meter', 'mét; đồng hồ đo', 'noun', '[{"en":"The swimming pool at our school is twenty-five meters long.","vi":"Hồ bơi ở trường chúng tôi dài hai mươi lăm mét."},{"en":"The tree in our yard is almost ten meters tall.","vi":"Cái cây trong sân nhà tôi cao gần mười mét."},{"en":"A man from the water company came to read the meter.","vi":"Một người của công ty cấp nước đã đến ghi chỉ số đồng hồ."}]', '[{"phrase":"square meter"},{"phrase":"read the meter"},{"phrase":"parking meter"},{"phrase":"gas meter"}]', 'Anh: metre · Mỹ: meter', '/ˈmiːtər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/met/meter/meter__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-04', 23, 'truck', 'xe tải', 'noun', '[{"en":"A big truck was blocking the road this morning.","vi":"Sáng nay có một chiếc xe tải lớn chắn ngang đường."},{"en":"My uncle drives a delivery truck for a living.","vi":"Chú tôi lái xe tải giao hàng để kiếm sống."},{"en":"We rented a truck to move our furniture to the new house.","vi":"Chúng tôi thuê một chiếc xe tải để chuyển đồ đạc sang nhà mới."}]', '[{"phrase":"truck driver"},{"phrase":"delivery truck"},{"phrase":"fire truck"},{"phrase":"drive a truck"}]', 'Anh: lorry · Mỹ: truck', '/trʌk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tru/truck/truck__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-04', 24, 'nose', 'mũi', 'noun', '[{"en":"My nose is running because I have a cold.","vi":"Tôi bị sổ mũi vì cảm lạnh."},{"en":"Please cover your nose and mouth when you sneeze.","vi":"Hãy che mũi và miệng khi bạn hắt hơi."},{"en":"He fell off his bike and broke his nose.","vi":"Anh ấy ngã xe đạp và bị gãy mũi."}]', '[{"phrase":"runny nose"},{"phrase":"blow your nose"},{"phrase":"broken nose"}]', NULL, '/nəʊz/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/nos/nose_/nose__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-04', 25, 'beside', 'bên cạnh', 'preposition', '[{"en":"Come and sit beside me on the sofa.","vi":"Lại đây ngồi cạnh tôi trên ghế sofa."},{"en":"There''s a small coffee shop beside the train station.","vi":"Có một quán cà phê nhỏ bên cạnh ga tàu."},{"en":"She always keeps a glass of water beside her bed.","vi":"Cô ấy luôn để một cốc nước bên cạnh giường."}]', '[{"phrase":"sit beside"},{"phrase":"beside the road"},{"phrase":"beside the river"}]', 'beside (bên cạnh) ≠ besides (ngoài ra)', '/bɪˈsaɪd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bes/besid/beside__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-04', 26, 'sail', 'đi thuyền (buồm); (tàu) khởi hành', 'verb', '[{"en":"We sailed around the islands for a whole week.","vi":"Chúng tôi đi thuyền vòng quanh các hòn đảo suốt một tuần."},{"en":"My grandfather taught me how to sail when I was ten.","vi":"Ông dạy tôi lái thuyền buồm khi tôi mười tuổi."},{"en":"The ship sails at six o''clock tomorrow morning.","vi":"Con tàu sẽ khởi hành lúc sáu giờ sáng mai."}]', '[{"phrase":"go sailing"},{"phrase":"set sail"},{"phrase":"sail across"}]', NULL, '/seɪl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sai/sail_/sail__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-04', 27, 'disaster', 'thảm họa; chuyện thất bại, tệ hại', 'noun', '[{"en":"The flood was the worst natural disaster in the region''s history.","vi":"Trận lũ là thảm họa thiên nhiên tồi tệ nhất trong lịch sử khu vực."},{"en":"Our first camping trip was a complete disaster.","vi":"Chuyến cắm trại đầu tiên của chúng tôi là một thất bại hoàn toàn."},{"en":"Check the weather first, or the picnic could end in disaster.","vi":"Hãy xem thời tiết trước, không thì buổi dã ngoại có thể kết thúc tệ hại."}]', '[{"phrase":"natural disaster"},{"phrase":"complete disaster"},{"phrase":"end in disaster"}]', NULL, '/dɪˈzæstər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dis/disas/disaster__us_4.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-04', 28, 'pace', 'tốc độ, nhịp độ', 'noun', '[{"en":"He walks at such a fast pace that it''s hard to keep up.","vi":"Anh ấy đi nhanh đến mức rất khó theo kịp."},{"en":"I prefer the slower pace of life in the countryside.","vi":"Tôi thích nhịp sống chậm rãi hơn ở vùng quê."},{"en":"With online courses, students can learn at their own pace.","vi":"Với các khóa học trực tuyến, học sinh có thể học theo tốc độ của riêng mình."}]', '[{"phrase":"pace of life"},{"phrase":"at your own pace"},{"phrase":"fast pace"},{"phrase":"keep pace with"}]', NULL, '/peɪs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pac/pace_/pace__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-04', 29, 'heavily', '(mưa) to, nặng hạt; nhiều, nặng nề', 'adverb', '[{"en":"It rained heavily all night, so the streets flooded.","vi":"Trời mưa to suốt đêm nên đường phố bị ngập."},{"en":"He was breathing heavily after running up the stairs.","vi":"Anh ấy thở nặng nhọc sau khi chạy lên cầu thang."},{"en":"The town depends heavily on tourism for jobs.","vi":"Thị trấn phụ thuộc nhiều vào du lịch để tạo việc làm."}]', '[{"phrase":"rain heavily"},{"phrase":"depend heavily on"},{"phrase":"breathe heavily"},{"phrase":"heavily influenced"}]', NULL, '/ˈhevɪli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hea/heavi/heavily__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-04', 30, 'devote', 'cống hiến; dành (thời gian, công sức)', 'verb', '[{"en":"She devoted her whole life to helping poor children.","vi":"Bà ấy đã cống hiến cả cuộc đời để giúp đỡ trẻ em nghèo."},{"en":"I devote an hour every evening to learning English.","vi":"Mỗi tối tôi dành một tiếng để học tiếng Anh."},{"en":"The whole meeting was devoted to planning next year''s budget.","vi":"Cả cuộc họp được dành để lên kế hoạch ngân sách cho năm tới."}]', '[{"phrase":"devote time to"},{"phrase":"devote your life to"},{"phrase":"devote attention to"}]', 'devote sth to sth/doing sth', '/dɪˈvəʊt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dev/devot/devote__us_1.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-5-05', 'ngsl-5', 'Thông dụng 2.001–2.500 · Bộ 5', 'New General Service List, thứ hạng 2.001–2.500', '#3da9fc', 'BookOpen', 5);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-05', 1, 'terrorist', 'kẻ khủng bố', 'noun', '[{"en":"Police arrested two terrorists before they could carry out an attack.","vi":"Cảnh sát đã bắt giữ hai kẻ khủng bố trước khi chúng kịp thực hiện một vụ tấn công."},{"en":"The airport increased security after warnings about a possible terrorist threat.","vi":"Sân bay đã tăng cường an ninh sau những cảnh báo về mối đe dọa khủng bố có thể xảy ra."},{"en":"The film is about a spy who tries to stop a group of terrorists.","vi":"Bộ phim kể về một điệp viên tìm cách ngăn chặn một nhóm khủng bố."}]', '[{"phrase":"terrorist attack"},{"phrase":"terrorist group"},{"phrase":"terrorist threat"}]', NULL, '/ˈterərɪst/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/ter/terro/terrorist__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-05', 2, 'justify', 'biện minh; chứng minh là hợp lý', 'verb', '[{"en":"How can you justify spending so much money on a new phone?","vi":"Làm sao bạn biện minh được cho việc tiêu nhiều tiền như vậy vào một chiếc điện thoại mới?"},{"en":"The excellent results justified all our hard work on the project.","vi":"Kết quả xuất sắc đã cho thấy mọi công sức vất vả của chúng tôi cho dự án là xứng đáng."},{"en":"You don''t need to justify your decision to anyone.","vi":"Bạn không cần phải biện minh cho quyết định của mình với bất kỳ ai."}]', '[{"phrase":"justify a decision"},{"phrase":"justify the cost"},{"phrase":"difficult to justify"}]', NULL, '/ˈdʒʌstɪfaɪ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/j/jus/justi/justify__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-05', 3, 'vital', 'rất quan trọng, thiết yếu', 'adjective', '[{"en":"Regular exercise is vital for good health.","vi":"Tập thể dục thường xuyên rất quan trọng đối với sức khỏe."},{"en":"It is vital that you arrive on time for the exam.","vi":"Việc bạn đến đúng giờ dự thi là cực kỳ quan trọng."},{"en":"Water is vital to all living things on Earth.","vi":"Nước là thiết yếu đối với mọi sinh vật trên Trái Đất."}]', '[{"phrase":"vital role"},{"phrase":"vital importance"},{"phrase":"absolutely vital"},{"phrase":"vital information"}]', NULL, '/ˈvaɪtl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/vit/vital/vital__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-05', 4, 'fascinate', 'làm say mê; thu hút', 'verb', '[{"en":"Space has always fascinated my younger brother.","vi":"Vũ trụ luôn khiến em trai tôi say mê."},{"en":"The old stories about the city fascinate tourists from all over the world.","vi":"Những câu chuyện xưa về thành phố thu hút du khách từ khắp nơi trên thế giới."},{"en":"It fascinates me how quickly young children learn new languages.","vi":"Tôi thấy thật lý thú khi trẻ nhỏ học ngôn ngữ mới nhanh đến vậy."}]', '[{"phrase":"be fascinated by"},{"phrase":"continue to fascinate"}]', 'Tính từ: fascinating (hấp dẫn), fascinated (bị cuốn hút)', '/ˈfæsɪneɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fas/fasci/fascinate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-05', 5, 'external', 'bên ngoài', 'adjective', '[{"en":"The company hired an external expert to review its accounts.","vi":"Công ty đã thuê một chuyên gia bên ngoài để kiểm tra sổ sách kế toán."},{"en":"This cream is for external use only.","vi":"Loại kem này chỉ dùng ngoài da."},{"en":"Connect the external hard drive to your laptop to save the files.","vi":"Hãy kết nối ổ cứng gắn ngoài với máy tính xách tay để lưu các tệp."}]', '[{"phrase":"external hard drive"},{"phrase":"external factors"},{"phrase":"for external use"},{"phrase":"external walls"}]', 'Trái nghĩa: internal (bên trong)', '/ɪkˈstɜːrnl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ext/exter/external__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-05', 6, 'spare', 'dự phòng, dư; rảnh rỗi', 'adjective', '[{"en":"What do you like doing in your spare time?","vi":"Bạn thích làm gì vào thời gian rảnh?"},{"en":"We keep a spare key under the flowerpot by the door.","vi":"Chúng tôi để một chiếc chìa khóa dự phòng dưới chậu hoa cạnh cửa."},{"en":"You can sleep in the spare room tonight.","vi":"Tối nay bạn có thể ngủ ở phòng trống."}]', '[{"phrase":"spare time"},{"phrase":"spare key"},{"phrase":"spare room"},{"phrase":"spare parts"}]', NULL, '/sper/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/spa/spare/spare__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-05', 7, 'whenever', 'bất cứ khi nào; mỗi khi', 'conjunction', '[{"en":"Call me whenever you need help with your homework.","vi":"Hãy gọi cho tôi bất cứ khi nào bạn cần giúp làm bài tập."},{"en":"Whenever I visit my grandmother, she cooks my favorite soup.","vi":"Mỗi khi tôi đến thăm bà, bà lại nấu món súp tôi thích nhất."},{"en":"You can start the course whenever you are ready.","vi":"Bạn có thể bắt đầu khóa học bất cứ khi nào bạn sẵn sàng."}]', '[{"phrase":"whenever possible"},{"phrase":"whenever you like"},{"phrase":"whenever you want"}]', NULL, '/wenˈevər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/whe/whene/whenever__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-05', 8, 'depression', 'bệnh trầm cảm; suy thoái kinh tế', 'noun', '[{"en":"After losing his job, he suffered from depression for months.","vi":"Sau khi mất việc, anh ấy bị trầm cảm suốt nhiều tháng."},{"en":"Talking to a doctor can help people who are dealing with depression.","vi":"Nói chuyện với bác sĩ có thể giúp những người đang phải đối mặt với chứng trầm cảm."},{"en":"Many families lost their homes during the depression of the 1930s.","vi":"Nhiều gia đình đã mất nhà trong cuộc suy thoái kinh tế những năm 1930."}]', '[{"phrase":"suffer from depression"},{"phrase":"severe depression"},{"phrase":"economic depression"}]', NULL, '/dɪˈpreʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dep/depre/depression__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-05', 9, 'guilty', 'có lỗi, áy náy; có tội', 'adjective', '[{"en":"I feel guilty about forgetting my best friend''s birthday.","vi":"Tôi thấy có lỗi vì đã quên sinh nhật của bạn thân."},{"en":"The court found him guilty of stealing a car.","vi":"Tòa án tuyên anh ta phạm tội trộm xe hơi."},{"en":"Don''t feel guilty about taking a day off when you''re sick.","vi":"Đừng cảm thấy áy náy khi nghỉ một ngày lúc bạn bị ốm."}]', '[{"phrase":"feel guilty"},{"phrase":"found guilty"},{"phrase":"guilty of"},{"phrase":"guilty conscience"}]', 'guilty of + danh từ/V-ing', '/ˈɡɪlti/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gui/guilt/guilty__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-05', 10, 'underlie', 'làm nền tảng cho; là nguyên nhân sâu xa của', 'verb', '[{"en":"Poor sleep often underlies problems with memory and focus.","vi":"Ngủ kém thường là nguyên nhân sâu xa của các vấn đề về trí nhớ và sự tập trung."},{"en":"The same simple idea underlies all of her stories.","vi":"Cùng một ý tưởng đơn giản làm nền tảng cho tất cả các câu chuyện của cô ấy."},{"en":"Doctors are still trying to find the cause that underlies her headaches.","vi":"Các bác sĩ vẫn đang cố tìm ra nguyên nhân sâu xa gây ra những cơn đau đầu của cô ấy."}]', '[{"phrase":"underlying cause"},{"phrase":"underlying problem"},{"phrase":"underlying reason"}]', 'underlie – underlay – underlain; hay gặp dạng underlying (tiềm ẩn, cơ bản)', '/ˌʌndərˈlaɪ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/und/under/underlie__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-05', 11, 'mom', 'mẹ', 'noun', '[{"en":"My mom always makes pancakes on Sunday mornings.","vi":"Mẹ tôi luôn làm bánh kếp vào sáng Chủ nhật."},{"en":"Can I go to the park with my friends, Mom?","vi":"Mẹ ơi, con đi công viên với các bạn được không ạ?"},{"en":"Please tell your mom thanks for the delicious dinner.","vi":"Nhờ bạn cảm ơn mẹ bạn giúp mình vì bữa tối ngon miệng nhé."}]', '[{"phrase":"my mom"},{"phrase":"single mom"},{"phrase":"stay-at-home mom"},{"phrase":"working mom"}]', 'Anh: mum · Mỹ: mom', '/mɑːm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mom/mom__/mom__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-05', 12, 'distinction', 'sự phân biệt, khác biệt; loại xuất sắc', 'noun', '[{"en":"It''s important to make a clear distinction between facts and opinions.","vi":"Điều quan trọng là phải phân biệt rõ ràng giữa sự thật và ý kiến."},{"en":"Young children slowly learn the distinction between right and wrong.","vi":"Trẻ nhỏ dần dần học được sự khác biệt giữa đúng và sai."},{"en":"She graduated with distinction from a top music school.","vi":"Cô ấy tốt nghiệp loại xuất sắc từ một trường âm nhạc hàng đầu."}]', '[{"phrase":"make a distinction"},{"phrase":"clear distinction"},{"phrase":"distinction between"},{"phrase":"with distinction"}]', NULL, '/dɪˈstɪŋkʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dis/disti/distinction__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-05', 13, 'satisfaction', 'sự hài lòng, thỏa mãn', 'noun', '[{"en":"At our hotel, customer satisfaction is always our top priority.","vi":"Tại khách sạn của chúng tôi, sự hài lòng của khách hàng luôn là ưu tiên hàng đầu."},{"en":"She felt a deep sense of satisfaction when she finished the marathon.","vi":"Cô ấy cảm thấy vô cùng mãn nguyện khi hoàn thành cuộc chạy marathon."},{"en":"Many workers say job satisfaction matters more to them than money.","vi":"Nhiều người lao động nói rằng sự hài lòng trong công việc quan trọng với họ hơn tiền bạc."}]', '[{"phrase":"customer satisfaction"},{"phrase":"job satisfaction"},{"phrase":"sense of satisfaction"}]', NULL, '/ˌsætɪsˈfækʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sat/satis/satisfaction__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-05', 14, 'incorporate', 'kết hợp, đưa vào', 'verb', '[{"en":"We incorporated your suggestions into the final plan.","vi":"Chúng tôi đã đưa các đề xuất của bạn vào bản kế hoạch cuối cùng."},{"en":"Try to incorporate more vegetables into your daily meals.","vi":"Hãy cố gắng đưa thêm nhiều rau vào các bữa ăn hằng ngày."},{"en":"The new building incorporates many ideas for saving energy.","vi":"Tòa nhà mới kết hợp nhiều ý tưởng tiết kiệm năng lượng."}]', '[{"phrase":"incorporate into"},{"phrase":"incorporate ideas"},{"phrase":"incorporate changes"}]', 'incorporate something into something', '/ɪnˈkɔːrpəreɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inc/incor/incorporate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-05', 15, 'pour', 'rót, đổ; mưa như trút', 'verb', '[{"en":"Could you pour me a glass of water, please?","vi":"Bạn rót giúp tôi một cốc nước được không?"},{"en":"Pour the milk into the bowl and stir gently.","vi":"Đổ sữa vào bát rồi khuấy nhẹ."},{"en":"It poured all afternoon, so we stayed inside and played games.","vi":"Trời mưa như trút cả buổi chiều nên chúng tôi ở trong nhà chơi trò chơi."}]', '[{"phrase":"pour a drink"},{"phrase":"pour into"},{"phrase":"pouring rain"}]', NULL, '/pɔːr/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pou/pour_/pour__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-05', 16, 'sweep', 'quét; quét qua, tràn qua', 'verb', '[{"en":"Can you sweep the kitchen floor after dinner?","vi":"Bạn quét sàn bếp sau bữa tối được không?"},{"en":"He swept the leaves off the front steps.","vi":"Anh ấy quét lá khỏi bậc thềm trước nhà."},{"en":"A strong wind swept through the town last night.","vi":"Đêm qua một cơn gió mạnh đã quét qua thị trấn."}]', '[{"phrase":"sweep the floor"},{"phrase":"sweep away"},{"phrase":"sweep through"}]', 'sweep – swept – swept', '/swiːp/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/swe/sweep/sweep__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-05', 17, 'obligation', 'nghĩa vụ, bổn phận', 'noun', '[{"en":"Parents have an obligation to keep their children safe.","vi":"Cha mẹ có bổn phận giữ an toàn cho con cái."},{"en":"You are under no obligation to buy anything today.","vi":"Hôm nay bạn không bắt buộc phải mua gì cả."},{"en":"She felt an obligation to help her neighbors after the flood.","vi":"Cô ấy cảm thấy có nghĩa vụ giúp đỡ hàng xóm sau trận lũ."}]', '[{"phrase":"legal obligation"},{"phrase":"moral obligation"},{"phrase":"under no obligation"},{"phrase":"sense of obligation"}]', NULL, '/ˌɑːblɪˈɡeɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/obl/oblig/obligation__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-05', 18, 'sir', 'thưa ông, thưa ngài', 'noun', '[{"en":"Excuse me, sir, you just dropped your wallet.","vi":"Xin lỗi ông, ông vừa làm rơi ví."},{"en":"Can I help you find something, sir?","vi":"Thưa ông, tôi có thể giúp ông tìm gì không ạ?"},{"en":"Yes, sir, your table will be ready in five minutes.","vi":"Vâng thưa ông, bàn của ông sẽ sẵn sàng trong năm phút nữa."}]', '[{"phrase":"yes, sir"},{"phrase":"excuse me, sir"},{"phrase":"Dear Sir"}]', 'Cách gọi lịch sự với nam giới; với nữ giới dùng madam', '/sɜːr/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sir/sir__/sir__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-05', 19, 'evaluate', 'đánh giá', 'verb', '[{"en":"Teachers evaluate students'' progress at the end of each term.","vi":"Giáo viên đánh giá sự tiến bộ của học sinh vào cuối mỗi học kỳ."},{"en":"We need more time to evaluate the results of the survey.","vi":"Chúng ta cần thêm thời gian để đánh giá kết quả của cuộc khảo sát."},{"en":"How do you evaluate whether a website is reliable?","vi":"Bạn đánh giá thế nào để biết một trang web có đáng tin cậy không?"}]', '[{"phrase":"evaluate the results"},{"phrase":"evaluate performance"},{"phrase":"carefully evaluate"}]', NULL, '/ɪˈvæljueɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eva/evalu/evaluate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-05', 20, 'anger', 'sự tức giận, cơn giận', 'noun', '[{"en":"He couldn''t hide his anger when the flight was canceled again.","vi":"Anh ấy không giấu được cơn giận khi chuyến bay lại bị hủy."},{"en":"Try to count to ten before you react in anger.","vi":"Hãy thử đếm đến mười trước khi phản ứng trong cơn giận."},{"en":"There was a lot of anger about the new parking rules.","vi":"Quy định đỗ xe mới đã khiến nhiều người rất tức giận."}]', '[{"phrase":"in anger"},{"phrase":"express anger"},{"phrase":"control your anger"}]', NULL, '/ˈæŋɡər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ang/anger/anger__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-05', 21, 'pub', 'quán rượu (kiểu Anh)', 'noun', '[{"en":"Let''s meet at the pub after work on Friday.","vi":"Thứ Sáu tan làm mình gặp nhau ở quán rượu nhé."},{"en":"The village pub serves great food on Sundays.","vi":"Quán rượu trong làng phục vụ đồ ăn rất ngon vào Chủ nhật."},{"en":"We watched the big game at a local pub.","vi":"Chúng tôi xem trận đấu lớn ở một quán rượu gần nhà."}]', '[{"phrase":"go to the pub"},{"phrase":"local pub"},{"phrase":"village pub"},{"phrase":"pub quiz"}]', NULL, '/pʌb/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pub/pub__/pub__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-05', 22, 'perception', 'cách nhìn nhận, nhận thức; sự cảm nhận', 'noun', '[{"en":"Social media can change our perception of what is normal.","vi":"Mạng xã hội có thể thay đổi cách chúng ta nhìn nhận điều gì là bình thường."},{"en":"There is a common perception that city life is more stressful.","vi":"Có một quan niệm phổ biến rằng cuộc sống ở thành phố căng thẳng hơn."},{"en":"Being very tired can affect your perception of time.","vi":"Quá mệt mỏi có thể ảnh hưởng đến cảm nhận của bạn về thời gian."}]', '[{"phrase":"public perception"},{"phrase":"common perception"},{"phrase":"perception of"},{"phrase":"change perceptions"}]', NULL, '/pərˈsepʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/per/perce/perception__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-05', 23, 'naturally', 'một cách tự nhiên; dĩ nhiên; bẩm sinh', 'adverb', '[{"en":"Try to relax and speak naturally during the interview.","vi":"Hãy cố thư giãn và nói chuyện tự nhiên trong buổi phỏng vấn."},{"en":"Naturally, we were disappointed when the concert was canceled.","vi":"Dĩ nhiên là chúng tôi thất vọng khi buổi hòa nhạc bị hủy."},{"en":"Some people are naturally good at making new friends.","vi":"Có những người bẩm sinh đã giỏi kết bạn mới."}]', '[{"phrase":"come naturally"},{"phrase":"naturally occurring"},{"phrase":"speak naturally"}]', NULL, '/ˈnætʃrəli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/nat/natur/naturally__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-05', 24, 'currency', 'tiền tệ', 'noun', '[{"en":"You can exchange currency at the airport, but the rates are poor.","vi":"Bạn có thể đổi ngoại tệ ở sân bay, nhưng tỷ giá không tốt."},{"en":"The euro is the currency used in many European countries.","vi":"Đồng euro là đơn vị tiền tệ được dùng ở nhiều nước châu Âu."},{"en":"What is the local currency in Thailand?","vi":"Tiền tệ địa phương ở Thái Lan là gì?"}]', '[{"phrase":"foreign currency"},{"phrase":"local currency"},{"phrase":"exchange currency"},{"phrase":"currency exchange"}]', NULL, '/ˈkɜːrənsi/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cur/curre/currency__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-05', 25, 'database', 'cơ sở dữ liệu', 'noun', '[{"en":"All customer details are stored in a secure database.","vi":"Mọi thông tin khách hàng đều được lưu trong một cơ sở dữ liệu an toàn."},{"en":"Search the library database to find articles for your essay.","vi":"Hãy tra cơ sở dữ liệu của thư viện để tìm bài viết cho bài luận của bạn."},{"en":"We need to update the database with the new phone numbers.","vi":"Chúng ta cần cập nhật số điện thoại mới vào cơ sở dữ liệu."}]', '[{"phrase":"online database"},{"phrase":"update the database"},{"phrase":"search the database"}]', NULL, '/ˈdeɪtəbeɪs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dat/datab/database__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-05', 26, 'initially', 'ban đầu, lúc đầu', 'adverb', '[{"en":"Initially, I found the job hard, but now I enjoy it.","vi":"Lúc đầu tôi thấy công việc khó, nhưng giờ tôi rất thích nó."},{"en":"The trip was initially planned for June but was moved to August.","vi":"Chuyến đi ban đầu dự định vào tháng Sáu nhưng đã được dời sang tháng Tám."},{"en":"She initially said no, but later changed her mind.","vi":"Ban đầu cô ấy từ chối, nhưng sau đó đã đổi ý."}]', '[{"phrase":"initially planned"},{"phrase":"initially thought"},{"phrase":"initially reluctant"}]', NULL, '/ɪˈnɪʃəli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ini/initi/initially__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-05', 27, 'territory', 'lãnh thổ; địa bàn; lĩnh vực', 'noun', '[{"en":"Lions will fight to protect their territory from other lions.","vi":"Sư tử sẽ chiến đấu để bảo vệ lãnh thổ của chúng khỏi những con sư tử khác."},{"en":"Our sales team covers a large territory in the north.","vi":"Đội bán hàng của chúng tôi phụ trách một địa bàn rộng lớn ở phía bắc."},{"en":"Starting my own business was completely new territory for me.","vi":"Việc tự kinh doanh là một lĩnh vực hoàn toàn mới mẻ đối với tôi."}]', '[{"phrase":"mark its territory"},{"phrase":"new territory"},{"phrase":"sales territory"},{"phrase":"enemy territory"}]', NULL, '/ˈterətɔːri/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/ter/terri/territory__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-05', 28, 'stream', 'dòng suối; dòng (người, xe…) liên tục', 'noun', '[{"en":"We had a picnic next to a small stream in the forest.","vi":"Chúng tôi đi dã ngoại bên một con suối nhỏ trong rừng."},{"en":"A steady stream of customers came into the shop all morning.","vi":"Khách hàng nối tiếp nhau vào cửa hàng suốt cả buổi sáng."},{"en":"The children crossed the stream by jumping from rock to rock.","vi":"Bọn trẻ vượt suối bằng cách nhảy từ tảng đá này sang tảng đá khác."}]', '[{"phrase":"mountain stream"},{"phrase":"steady stream"},{"phrase":"constant stream"},{"phrase":"stream of traffic"}]', NULL, '/striːm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/str/strea/stream__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-05', 29, 'rarely', 'hiếm khi', 'adverb', '[{"en":"My dad rarely watches TV in the evening.","vi":"Bố tôi hiếm khi xem TV vào buổi tối."},{"en":"It rarely snows in this part of the country.","vi":"Ở vùng này của đất nước hiếm khi có tuyết."},{"en":"We rarely see each other now that she lives abroad.","vi":"Giờ cô ấy sống ở nước ngoài nên chúng tôi hiếm khi gặp nhau."}]', '[{"phrase":"very rarely"},{"phrase":"only rarely"},{"phrase":"rarely, if ever"}]', NULL, '/ˈrerli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rar/rarel/rarely__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-05', 30, 'height', 'chiều cao; độ cao; lúc cao điểm', 'noun', '[{"en":"The nurse measured my height and weight during the checkup.","vi":"Y tá đo chiều cao và cân nặng của tôi trong buổi khám sức khỏe."},{"en":"The plane is now flying at a height of 10,000 meters.","vi":"Máy bay hiện đang bay ở độ cao 10.000 mét."},{"en":"The beach is always crowded at the height of summer.","vi":"Bãi biển lúc nào cũng đông đúc vào giữa mùa hè cao điểm."}]', '[{"phrase":"average height"},{"phrase":"at a height of"},{"phrase":"at the height of"},{"phrase":"fear of heights"}]', 'Tính từ: high (cao)', '/haɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hei/heigh/height__us_1.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-5-06', 'ngsl-5', 'Thông dụng 2.001–2.500 · Bộ 6', 'New General Service List, thứ hạng 2.001–2.500', '#3da9fc', 'BookOpen', 6);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-06', 1, 'apparent', 'rõ ràng; có vẻ như', 'adjective', '[{"en":"It soon became apparent that nobody had read the instructions.","vi":"Chẳng bao lâu sau, rõ ràng là không ai đã đọc hướng dẫn."},{"en":"The problem was apparent as soon as we opened the box.","vi":"Vấn đề hiện rõ ngay khi chúng tôi mở hộp ra."},{"en":"Despite her apparent calm, she was very nervous before the exam.","vi":"Dù có vẻ bình tĩnh, cô ấy rất lo lắng trước kỳ thi."}]', '[{"phrase":"become apparent"},{"phrase":"apparent reason"},{"phrase":"for no apparent reason"},{"phrase":"immediately apparent"}]', NULL, '/əˈpærənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/app/appar/apparent__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-06', 2, 'western', '(thuộc) phương Tây; phía tây', 'adjective', '[{"en":"Many young people in the city enjoy Western food and music.","vi":"Nhiều bạn trẻ trong thành phố thích đồ ăn và âm nhạc phương Tây."},{"en":"We spent a week traveling along the western coast.","vi":"Chúng tôi dành một tuần du lịch dọc bờ biển phía tây."},{"en":"Rain is expected in western parts of the country tomorrow.","vi":"Ngày mai dự báo có mưa ở các vùng phía tây của đất nước."}]', '[{"phrase":"Western countries"},{"phrase":"Western culture"},{"phrase":"western coast"},{"phrase":"western part"}]', 'Viết hoa khi chỉ phương Tây (Western culture)', '/ˈwestərn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wes/weste/western__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-06', 3, 'expansion', 'sự mở rộng; sự phát triển', 'noun', '[{"en":"The company is planning a major expansion into Asian markets.","vi":"Công ty đang lên kế hoạch mở rộng lớn sang các thị trường châu Á."},{"en":"The airport expansion will create hundreds of new jobs.","vi":"Việc mở rộng sân bay sẽ tạo ra hàng trăm việc làm mới."},{"en":"Rapid expansion of the city has made traffic much worse.","vi":"Sự phát triển nhanh của thành phố đã khiến giao thông tệ hơn nhiều."}]', '[{"phrase":"rapid expansion"},{"phrase":"economic expansion"},{"phrase":"expansion plans"},{"phrase":"expansion into"}]', NULL, '/ɪkˈspænʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exp/expan/expansion__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-06', 4, 'constantly', 'liên tục; luôn luôn', 'adverb', '[{"en":"My little brother is constantly asking for snacks.","vi":"Em trai tôi lúc nào cũng đòi ăn vặt."},{"en":"Prices have been constantly rising over the past few months.","vi":"Giá cả đã liên tục tăng trong vài tháng qua."},{"en":"She checks her phone constantly, even during dinner.","vi":"Cô ấy liên tục kiểm tra điện thoại, ngay cả trong bữa tối."}]', '[{"phrase":"constantly changing"},{"phrase":"constantly complain"},{"phrase":"constantly worry"},{"phrase":"constantly check"}]', NULL, '/ˈkɑːnstəntli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcons/xconstantly__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-06', 5, 'muscle', 'cơ; cơ bắp', 'noun', '[{"en":"Swimming is a great way to build muscle without hurting your joints.","vi":"Bơi lội là cách tuyệt vời để tăng cơ mà không hại khớp."},{"en":"I pulled a muscle in my back while lifting a heavy box.","vi":"Tôi bị căng cơ lưng khi nâng một chiếc hộp nặng."},{"en":"My leg muscles were sore after the long hike.","vi":"Cơ chân tôi bị đau nhức sau chuyến đi bộ đường dài."}]', '[{"phrase":"build muscle"},{"phrase":"pull a muscle"},{"phrase":"muscle pain"},{"phrase":"leg muscles"}]', NULL, '/ˈmʌsl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mus/muscl/muscle__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-06', 6, 'scare', 'làm sợ; dọa', 'verb', '[{"en":"You really scared me when you walked in so quietly.","vi":"Bạn đi vào nhẹ nhàng quá làm tôi giật cả mình."},{"en":"Loud thunder always scares our dog, so he hides under the bed.","vi":"Tiếng sấm to luôn làm con chó nhà tôi sợ, nên nó trốn dưới gầm giường."},{"en":"Don''t let one bad experience scare you away from traveling.","vi":"Đừng để một trải nghiệm tồi tệ khiến bạn sợ không dám đi du lịch nữa."}]', '[{"phrase":"scare someone"},{"phrase":"scare away"},{"phrase":"scare off"},{"phrase":"easily scared"}]', 'be scared of = sợ cái gì', '/sker/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sca/scare/scare__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-06', 7, 'badly', 'tệ; nặng; rất (cần)', 'adverb', '[{"en":"I did badly on the math test because I didn''t study.","vi":"Tôi làm bài kiểm tra toán rất tệ vì đã không học bài."},{"en":"Many trees were badly damaged in the storm last night.","vi":"Nhiều cây cối bị hư hại nặng trong cơn bão tối qua."},{"en":"This old house badly needs a new roof.","vi":"Căn nhà cũ này rất cần một mái nhà mới."}]', '[{"phrase":"badly injured"},{"phrase":"badly damaged"},{"phrase":"badly need"},{"phrase":"go badly"}]', 'badly – worse – worst', '/ˈbædli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bad/badly/badly__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-06', 8, 'everyday', 'hằng ngày; thường ngày', 'adjective', '[{"en":"Smartphones have become an important part of everyday life.","vi":"Điện thoại thông minh đã trở thành một phần quan trọng của cuộc sống hằng ngày."},{"en":"These simple tips can help you save money on everyday items.","vi":"Những mẹo đơn giản này giúp bạn tiết kiệm tiền cho các món đồ dùng hằng ngày."},{"en":"He wore his everyday clothes to the party.","vi":"Anh ấy mặc quần áo thường ngày đến bữa tiệc."}]', '[{"phrase":"everyday life"},{"phrase":"everyday use"},{"phrase":"everyday items"},{"phrase":"everyday language"}]', 'everyday (tính từ) ≠ every day (mỗi ngày)', '/ˈevrideɪ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eve/every/everyday__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-06', 9, 'boundary', 'ranh giới; giới hạn', 'noun', '[{"en":"The river forms the boundary between the two towns.","vi":"Con sông tạo thành ranh giới giữa hai thị trấn."},{"en":"It''s important to set clear boundaries with your coworkers.","vi":"Việc đặt ra giới hạn rõ ràng với đồng nghiệp là rất quan trọng."},{"en":"A small fence marks the boundary of our garden.","vi":"Một hàng rào nhỏ đánh dấu ranh giới khu vườn nhà chúng tôi."}]', '[{"phrase":"set boundaries"},{"phrase":"boundary between"},{"phrase":"mark the boundary"},{"phrase":"cross the boundary"}]', NULL, '/ˈbaʊndri/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bou/bound/boundary__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-06', 10, 'ratio', 'tỉ lệ; tỉ số', 'noun', '[{"en":"The ratio of students to teachers in this school is twenty to one.","vi":"Tỉ lệ học sinh trên giáo viên ở trường này là hai mươi trên một."},{"en":"Mix the rice and water in a ratio of one to two.","vi":"Trộn gạo và nước theo tỉ lệ một phần gạo, hai phần nước."},{"en":"Our class has a high ratio of girls to boys.","vi":"Lớp chúng tôi có tỉ lệ nữ so với nam cao."}]', '[{"phrase":"ratio of"},{"phrase":"high ratio"},{"phrase":"in a ratio of"},{"phrase":"student-teacher ratio"}]', NULL, '/ˈreɪʃiəʊ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rat/ratio/ratio__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-06', 11, 'essay', 'bài luận; bài tiểu luận', 'noun', '[{"en":"I have to write a two-page essay about my hometown.","vi":"Tôi phải viết một bài luận dài hai trang về quê hương mình."},{"en":"Did you hand in your history essay on time?","vi":"Bạn đã nộp bài luận môn lịch sử đúng hạn chưa?"},{"en":"Her essay won first prize in the school competition.","vi":"Bài luận của cô ấy đã đoạt giải nhất trong cuộc thi của trường."}]', '[{"phrase":"write an essay"},{"phrase":"hand in an essay"},{"phrase":"essay about"},{"phrase":"short essay"}]', NULL, '/ˈeseɪ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ess/essay/essay__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-06', 12, 'scream', 'hét lên; la hét', 'verb', '[{"en":"The kids screamed with excitement on the roller coaster.","vi":"Bọn trẻ hét lên vì phấn khích trên tàu lượn siêu tốc."},{"en":"She screamed when she saw a snake in the kitchen.","vi":"Cô ấy hét lên khi nhìn thấy một con rắn trong bếp."},{"en":"Please stop screaming at each other and talk calmly.","vi":"Làm ơn đừng hét vào mặt nhau nữa và hãy nói chuyện bình tĩnh."}]', '[{"phrase":"scream at"},{"phrase":"scream for help"},{"phrase":"scream with excitement"},{"phrase":"scream in pain"}]', NULL, '/skriːm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/scr/screa/scream__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-06', 13, 'withdraw', 'rút (tiền); rút lui; rút khỏi', 'verb', '[{"en":"I need to withdraw some cash before we go to the market.","vi":"Tôi cần rút ít tiền mặt trước khi chúng ta đi chợ."},{"en":"He withdrew from the race because of a knee injury.","vi":"Anh ấy rút khỏi cuộc đua vì chấn thương đầu gối."},{"en":"The company decided to withdraw its offer after the meeting.","vi":"Công ty quyết định rút lại lời đề nghị sau cuộc họp."}]', '[{"phrase":"withdraw money"},{"phrase":"withdraw cash"},{"phrase":"withdraw from"},{"phrase":"withdraw an offer"}]', 'withdraw – withdrew – withdrawn', '/wɪðˈdrɔː/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wit/withd/withdraw__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-06', 14, 'pollution', 'sự ô nhiễm', 'noun', '[{"en":"Air pollution in big cities is getting worse every year.","vi":"Ô nhiễm không khí ở các thành phố lớn ngày càng tệ hơn mỗi năm."},{"en":"We can reduce pollution by taking the bus instead of driving.","vi":"Chúng ta có thể giảm ô nhiễm bằng cách đi xe buýt thay vì lái xe."},{"en":"Plastic pollution is a serious problem for sea animals.","vi":"Ô nhiễm nhựa là một vấn đề nghiêm trọng đối với động vật biển."}]', '[{"phrase":"air pollution"},{"phrase":"water pollution"},{"phrase":"reduce pollution"},{"phrase":"noise pollution"}]', 'Không đếm được', '/pəˈluːʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pol/pollu/pollution__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-06', 15, 'disorder', 'chứng rối loạn; sự lộn xộn', 'noun', '[{"en":"She was diagnosed with a sleep disorder last year.","vi":"Năm ngoái cô ấy được chẩn đoán mắc chứng rối loạn giấc ngủ."},{"en":"The doctor said my skin disorder was not serious.","vi":"Bác sĩ nói chứng rối loạn da của tôi không nghiêm trọng."},{"en":"After the party, the whole house was in complete disorder.","vi":"Sau bữa tiệc, cả căn nhà hoàn toàn lộn xộn."}]', '[{"phrase":"sleep disorder"},{"phrase":"skin disorder"},{"phrase":"mental disorder"},{"phrase":"in disorder"}]', NULL, '/dɪsˈɔːrdər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dis/disor/disorder__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-06', 16, 'furniture', 'đồ nội thất; đồ đạc', 'noun', '[{"en":"We bought some new furniture for the living room.","vi":"Chúng tôi đã mua ít đồ nội thất mới cho phòng khách."},{"en":"Can you help me move this heavy furniture upstairs?","vi":"Bạn có thể giúp tôi chuyển đống đồ đạc nặng này lên lầu không?"},{"en":"The only piece of furniture in the room was an old bed.","vi":"Món đồ nội thất duy nhất trong phòng là một chiếc giường cũ."}]', '[{"phrase":"piece of furniture"},{"phrase":"move furniture"},{"phrase":"office furniture"},{"phrase":"new furniture"}]', 'Không đếm được: a piece of furniture', '/ˈfɜːrnɪtʃər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fur/furni/furniture__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-06', 17, 'symbol', 'biểu tượng; ký hiệu', 'noun', '[{"en":"The dove is often used as a symbol of peace.","vi":"Chim bồ câu thường được dùng làm biểu tượng của hòa bình."},{"en":"What does this small symbol on the washing machine mean?","vi":"Ký hiệu nhỏ này trên máy giặt có nghĩa là gì?"},{"en":"For many families, a big house is a symbol of success.","vi":"Với nhiều gia đình, một ngôi nhà lớn là biểu tượng của thành công."}]', '[{"phrase":"symbol of"},{"phrase":"national symbol"},{"phrase":"status symbol"},{"phrase":"chemical symbol"}]', NULL, '/ˈsɪmbl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sym/symbo/symbol__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-06', 18, 'apartment', 'căn hộ', 'noun', '[{"en":"They rent a small apartment near the city center.","vi":"Họ thuê một căn hộ nhỏ gần trung tâm thành phố."},{"en":"Our apartment is on the fifth floor, and there''s no elevator.","vi":"Căn hộ của chúng tôi ở tầng năm, và không có thang máy."},{"en":"I''m looking for a two-bedroom apartment with a balcony.","vi":"Tôi đang tìm một căn hộ hai phòng ngủ có ban công."}]', '[{"phrase":"rent an apartment"},{"phrase":"apartment building"},{"phrase":"two-bedroom apartment"},{"phrase":"small apartment"}]', 'Anh: flat · Mỹ: apartment', '/əˈpɑːrtmənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/apa/apart/apartment__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-06', 19, 'demonstration', 'cuộc biểu tình; sự trình diễn, minh họa', 'noun', '[{"en":"Thousands of people joined the demonstration in the main square.","vi":"Hàng nghìn người đã tham gia cuộc biểu tình ở quảng trường chính."},{"en":"The salesperson gave us a quick demonstration of the new vacuum cleaner.","vi":"Nhân viên bán hàng đã trình diễn nhanh cho chúng tôi cách dùng chiếc máy hút bụi mới."},{"en":"After a short demonstration, the students tried the experiment themselves.","vi":"Sau một phần minh họa ngắn, học sinh tự làm thí nghiệm."}]', '[{"phrase":"give a demonstration"},{"phrase":"hold a demonstration"},{"phrase":"peaceful demonstration"},{"phrase":"demonstration of"}]', NULL, '/ˌdemənˈstreɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dem/demon/demonstration__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-06', 20, 'analyst', 'nhà phân tích; chuyên viên phân tích', 'noun', '[{"en":"My sister works as a financial analyst at a large bank.","vi":"Chị tôi làm chuyên viên phân tích tài chính ở một ngân hàng lớn."},{"en":"Analysts expect house prices to fall slightly next year.","vi":"Các nhà phân tích dự đoán giá nhà sẽ giảm nhẹ vào năm tới."},{"en":"The company hired a data analyst to study customer behavior.","vi":"Công ty đã thuê một chuyên viên phân tích dữ liệu để nghiên cứu hành vi khách hàng."}]', '[{"phrase":"financial analyst"},{"phrase":"data analyst"},{"phrase":"market analyst"},{"phrase":"analysts expect"}]', NULL, '/ˈænəlɪst/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ana/analy/analyst__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-06', 21, 'platform', 'sân ga; nền tảng; bục', 'noun', '[{"en":"The train to the airport leaves from platform three.","vi":"Tàu đi sân bay khởi hành từ sân ga số ba."},{"en":"Many small businesses sell their products on online platforms.","vi":"Nhiều doanh nghiệp nhỏ bán sản phẩm trên các nền tảng trực tuyến."},{"en":"The speaker walked onto the platform and thanked the audience.","vi":"Diễn giả bước lên bục và cảm ơn khán giả."}]', '[{"phrase":"train platform"},{"phrase":"online platform"},{"phrase":"social media platform"},{"phrase":"on the platform"}]', NULL, '/ˈplætfɔːrm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pla/platf/platform__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-06', 22, 'steel', 'thép', 'noun', '[{"en":"The bridge is made of steel and concrete.","vi":"Cây cầu được làm bằng thép và bê tông."},{"en":"I prefer stainless steel pans because they last longer.","vi":"Tôi thích chảo bằng thép không gỉ hơn vì chúng bền hơn."},{"en":"My grandfather worked in a steel factory for thirty years.","vi":"Ông tôi đã làm việc ở một nhà máy thép suốt ba mươi năm."}]', '[{"phrase":"stainless steel"},{"phrase":"made of steel"},{"phrase":"steel industry"},{"phrase":"steel frame"}]', 'Không đếm được', '/stiːl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/ste/steel/steel__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-06', 23, 'cake', 'bánh ngọt; bánh kem', 'noun', '[{"en":"Mom baked a chocolate cake for my birthday.","vi":"Mẹ đã nướng một chiếc bánh sô-cô-la cho sinh nhật tôi."},{"en":"Would you like another piece of cake with your tea?","vi":"Bạn có muốn thêm một miếng bánh ngọt để ăn cùng trà không?"},{"en":"We ordered a big wedding cake from a local bakery.","vi":"Chúng tôi đã đặt một chiếc bánh cưới lớn ở một tiệm bánh gần nhà."}]', '[{"phrase":"bake a cake"},{"phrase":"birthday cake"},{"phrase":"piece of cake"},{"phrase":"chocolate cake"}]', 'a piece of cake (thành ngữ) = dễ ợt', '/keɪk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cak/cake_/cake__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-06', 24, 'transform', 'biến đổi; thay đổi hoàn toàn', 'verb', '[{"en":"The internet has transformed the way we work and study.","vi":"Internet đã thay đổi hoàn toàn cách chúng ta làm việc và học tập."},{"en":"They transformed an old warehouse into a modern café.","vi":"Họ đã biến một nhà kho cũ thành một quán cà phê hiện đại."},{"en":"A little paint can completely transform a small room.","vi":"Một chút sơn có thể làm căn phòng nhỏ thay đổi hoàn toàn."}]', '[{"phrase":"transform into"},{"phrase":"completely transform"},{"phrase":"transform the way"},{"phrase":"transform lives"}]', 'transform A into B = biến A thành B', '/trænsˈfɔːrm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tra/trans/transform__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-06', 25, 'wound', 'vết thương', 'noun', '[{"en":"The nurse cleaned the wound and put on a bandage.","vi":"Y tá đã rửa vết thương và băng lại."},{"en":"It took several weeks for the wound on his leg to heal.","vi":"Phải mất vài tuần vết thương ở chân anh ấy mới lành."},{"en":"Keep the wound dry and change the bandage every day.","vi":"Hãy giữ vết thương khô ráo và thay băng mỗi ngày."}]', '[{"phrase":"clean a wound"},{"phrase":"the wound heals"},{"phrase":"deep wound"},{"phrase":"keep the wound dry"}]', 'wound /wuːnd/ (vết thương) ≠ wound /waʊnd/ (quá khứ của wind)', '/ˈwaʊnd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-06', 26, 'restriction', 'sự hạn chế; quy định hạn chế', 'noun', '[{"en":"There are strict restrictions on what you can take on a plane.","vi":"Có những quy định hạn chế nghiêm ngặt về đồ được mang lên máy bay."},{"en":"The city introduced new parking restrictions in the downtown area.","vi":"Thành phố đã đưa ra các quy định hạn chế đỗ xe mới ở khu trung tâm."},{"en":"Most travel restrictions were lifted at the end of the year.","vi":"Hầu hết các hạn chế đi lại đã được dỡ bỏ vào cuối năm."}]', '[{"phrase":"strict restrictions"},{"phrase":"restrictions on"},{"phrase":"lift restrictions"},{"phrase":"travel restrictions"}]', 'restriction on sth', '/rɪˈstrɪkʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/res/restr/restriction__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-06', 27, 'foundation', 'nền tảng; móng (nhà); quỹ', 'noun', '[{"en":"Good habits in childhood lay the foundation for a healthy life.","vi":"Thói quen tốt từ nhỏ đặt nền tảng cho một cuộc sống khỏe mạnh."},{"en":"Workers are pouring the foundation for the new school building.","vi":"Công nhân đang đổ móng cho tòa nhà trường học mới."},{"en":"The foundation gives scholarships to students from poor families.","vi":"Quỹ này trao học bổng cho sinh viên từ các gia đình nghèo."}]', '[{"phrase":"lay the foundation"},{"phrase":"strong foundation"},{"phrase":"foundation for"},{"phrase":"charitable foundation"}]', NULL, '/faʊnˈdeɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fou/found/foundation__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-06', 28, 'designer', 'nhà thiết kế', 'noun', '[{"en":"She dreams of becoming a famous fashion designer.","vi":"Cô ấy mơ trở thành một nhà thiết kế thời trang nổi tiếng."},{"en":"We hired a designer to create a new logo for our shop.","vi":"Chúng tôi đã thuê một nhà thiết kế để làm logo mới cho cửa hàng."},{"en":"The game designers spent two years working on this project.","vi":"Các nhà thiết kế trò chơi đã dành hai năm cho dự án này."}]', '[{"phrase":"fashion designer"},{"phrase":"graphic designer"},{"phrase":"interior designer"},{"phrase":"game designer"}]', NULL, '/dɪˈzaɪnər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/des/desig/designer__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-06', 29, 'strain', 'sự căng thẳng; áp lực', 'noun', '[{"en":"Working two jobs put a lot of strain on his health.","vi":"Làm hai công việc đã gây nhiều áp lực lên sức khỏe của anh ấy."},{"en":"Looking at a screen all day can cause eye strain.","vi":"Nhìn màn hình cả ngày có thể gây mỏi mắt."},{"en":"Money problems can put a strain on any marriage.","vi":"Chuyện tiền bạc có thể gây căng thẳng cho bất kỳ cuộc hôn nhân nào."}]', '[{"phrase":"put a strain on"},{"phrase":"under strain"},{"phrase":"eye strain"},{"phrase":"financial strain"}]', NULL, '/streɪn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/str/strai/strain__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-06', 30, 'innovation', 'sự đổi mới; sáng kiến', 'noun', '[{"en":"The company encourages innovation by letting staff test their own ideas.","vi":"Công ty khuyến khích sự đổi mới bằng cách cho nhân viên thử nghiệm ý tưởng của riêng họ."},{"en":"Online banking was a major innovation for many customers.","vi":"Ngân hàng trực tuyến là một sáng kiến lớn đối với nhiều khách hàng."},{"en":"Our city needs more innovation in public transportation.","vi":"Thành phố chúng ta cần đổi mới nhiều hơn trong giao thông công cộng."}]', '[{"phrase":"technological innovation"},{"phrase":"encourage innovation"},{"phrase":"innovation in"},{"phrase":"major innovation"}]', NULL, '/ˌɪnəˈveɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inn/innov/innovation__us_1.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-5-07', 'ngsl-5', 'Thông dụng 2.001–2.500 · Bộ 7', 'New General Service List, thứ hạng 2.001–2.500', '#3da9fc', 'BookOpen', 7);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-07', 1, 'album', 'album nhạc; cuốn album ảnh', 'noun', '[{"en":"The band is releasing a new album next month.","vi":"Ban nhạc sẽ phát hành album mới vào tháng sau."},{"en":"I listened to her first album all the way home.","vi":"Tôi đã nghe album đầu tiên của cô ấy suốt đường về nhà."},{"en":"My grandmother keeps old family photos in a big album.","vi":"Bà tôi cất những tấm ảnh gia đình cũ trong một cuốn album lớn."}]', '[{"phrase":"new album"},{"phrase":"release an album"},{"phrase":"photo album"},{"phrase":"debut album"}]', NULL, '/ˈælbəm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/alb/album/album__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-07', 2, 'singer', 'ca sĩ; người hát', 'noun', '[{"en":"She dreamed of becoming a famous singer when she was young.","vi":"Hồi nhỏ cô ấy mơ trở thành một ca sĩ nổi tiếng."},{"en":"The lead singer thanked the crowd after the last song.","vi":"Ca sĩ hát chính cảm ơn khán giả sau bài hát cuối cùng."},{"en":"My brother isn''t a great singer, but he loves karaoke.","vi":"Anh tôi hát không hay lắm, nhưng anh ấy rất thích karaoke."}]', '[{"phrase":"lead singer"},{"phrase":"famous singer"},{"phrase":"pop singer"},{"phrase":"opera singer"}]', NULL, '/ˈsɪŋər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sin/singe/singer__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-07', 3, 'trail', 'đường mòn; dấu vết', 'noun', '[{"en":"We followed a narrow trail up the side of the mountain.","vi":"Chúng tôi đi theo một con đường mòn hẹp lên sườn núi."},{"en":"This hiking trail is closed during the rainy season.","vi":"Đường mòn đi bộ này bị đóng vào mùa mưa."},{"en":"The dog left a trail of muddy footprints across the kitchen.","vi":"Con chó để lại một vệt dấu chân lấm bùn khắp nhà bếp."}]', '[{"phrase":"hiking trail"},{"phrase":"follow a trail"},{"phrase":"mountain trail"},{"phrase":"a trail of"}]', NULL, '/treɪl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tra/trail/trail__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-07', 4, 'trap', 'cái bẫy; cạm bẫy', 'noun', '[{"en":"We set a trap to catch the mouse in the kitchen.","vi":"Chúng tôi đặt một cái bẫy để bắt con chuột trong bếp."},{"en":"Don''t fall into the trap of spending more than you earn.","vi":"Đừng rơi vào cái bẫy tiêu nhiều hơn số tiền mình kiếm được."},{"en":"She realized too late that the cheap offer was a trap.","vi":"Cô ấy nhận ra quá muộn rằng lời mời chào giá rẻ đó là một cái bẫy."}]', '[{"phrase":"set a trap"},{"phrase":"fall into the trap"},{"phrase":"caught in a trap"},{"phrase":"tourist trap"}]', NULL, '/træp/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tra/trap_/trap__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-07', 5, 'loose', 'lỏng; lung lay; rộng (quần áo)', 'adjective', '[{"en":"One of the screws on this chair is loose.","vi":"Một con ốc trên chiếc ghế này bị lỏng."},{"en":"She prefers to wear loose clothes when the weather is hot.","vi":"Cô ấy thích mặc quần áo rộng khi trời nóng."},{"en":"My little son has a loose tooth and keeps touching it.","vi":"Con trai nhỏ của tôi có một cái răng lung lay và cứ sờ vào nó."}]', '[{"phrase":"loose clothes"},{"phrase":"come loose"},{"phrase":"loose tooth"},{"phrase":"break loose"}]', 'loose (lỏng) ≠ lose (mất)', '/luːs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/loo/loose/loose__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-07', 6, 'extension', 'sự gia hạn; phần mở rộng; số máy lẻ', 'noun', '[{"en":"I asked my teacher for an extension on the essay.","vi":"Tôi xin cô giáo gia hạn nộp bài luận."},{"en":"They are building an extension at the back of their house.","vi":"Họ đang xây phần nhà mở rộng ở phía sau nhà mình."},{"en":"You can reach me at extension 214 during office hours.","vi":"Bạn có thể gọi cho tôi qua số máy lẻ 214 trong giờ hành chính."}]', '[{"phrase":"ask for an extension"},{"phrase":"get an extension"},{"phrase":"extension cord"},{"phrase":"build an extension"}]', NULL, '/ɪkˈstenʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ext/exten/extension__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-07', 7, 'wealth', 'sự giàu có; của cải; sự phong phú', 'noun', '[{"en":"Money and wealth do not always bring happiness.","vi":"Tiền bạc và sự giàu có không phải lúc nào cũng mang lại hạnh phúc."},{"en":"Most of his wealth came from the family business.","vi":"Phần lớn của cải của ông ấy đến từ công việc kinh doanh của gia đình."},{"en":"Our new manager brings a wealth of experience to the team.","vi":"Người quản lý mới mang đến cho nhóm rất nhiều kinh nghiệm."}]', '[{"phrase":"a wealth of"},{"phrase":"great wealth"},{"phrase":"create wealth"},{"phrase":"wealth and power"}]', 'không đếm được', '/welθ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wea/wealt/wealth__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-07', 8, 'gradually', 'dần dần; từ từ', 'adverb', '[{"en":"The weather gradually got warmer as spring arrived.","vi":"Thời tiết ấm dần lên khi mùa xuân đến."},{"en":"Her English improved gradually after she moved to London.","vi":"Tiếng Anh của cô ấy dần dần tiến bộ sau khi chuyển đến London."},{"en":"Add the sugar gradually and keep stirring the mixture.","vi":"Cho đường vào từ từ và tiếp tục khuấy hỗn hợp."}]', '[{"phrase":"gradually increase"},{"phrase":"gradually improve"},{"phrase":"gradually become"}]', NULL, '/ˈɡrædʒuəli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gra/gradu/gradually__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-07', 9, 'tank', 'bể chứa; bình (xăng, nước); xe tăng', 'noun', '[{"en":"We need to fill the tank before the long drive.","vi":"Chúng ta cần đổ đầy bình xăng trước chuyến đi dài."},{"en":"My kids feed the fish in the tank every morning.","vi":"Các con tôi cho cá trong bể ăn mỗi sáng."},{"en":"An old army tank stands outside the war museum.","vi":"Một chiếc xe tăng quân đội cũ đặt bên ngoài bảo tàng chiến tranh."}]', '[{"phrase":"fuel tank"},{"phrase":"fish tank"},{"phrase":"water tank"},{"phrase":"fill the tank"}]', NULL, '/tæŋk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tan/tank_/tank__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-07', 10, 'evil', 'độc ác; xấu xa', 'adjective', '[{"en":"In the movie, an evil queen tries to kill the princess.","vi":"Trong phim, một mụ hoàng hậu độc ác tìm cách giết công chúa."},{"en":"The story is about a brave boy who fights an evil wizard.","vi":"Câu chuyện kể về một cậu bé dũng cảm chiến đấu với một phù thủy độc ác."},{"en":"He isn''t evil; he just made some bad choices.","vi":"Anh ta không xấu xa; anh ta chỉ đưa ra vài lựa chọn sai lầm."}]', '[{"phrase":"evil spirit"},{"phrase":"evil queen"},{"phrase":"good and evil"},{"phrase":"pure evil"}]', NULL, '/ˈiːvl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/evi/evil_/evil__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-07', 11, 'remarkable', 'đáng chú ý; đáng kinh ngạc; phi thường', 'adjective', '[{"en":"She made a remarkable recovery after the accident.","vi":"Cô ấy đã hồi phục đáng kinh ngạc sau vụ tai nạn."},{"en":"It''s remarkable how quickly children learn new languages.","vi":"Thật đáng kinh ngạc khi trẻ em học ngôn ngữ mới nhanh đến vậy."},{"en":"Our team has achieved remarkable results this year.","vi":"Năm nay nhóm chúng tôi đã đạt được những kết quả phi thường."}]', '[{"phrase":"remarkable achievement"},{"phrase":"remarkable recovery"},{"phrase":"truly remarkable"},{"phrase":"remarkable results"}]', NULL, '/rɪˈmɑːrkəbl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rem/remar/remarkable__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-07', 12, 'tune', 'giai điệu; điệu nhạc', 'noun', '[{"en":"He was whistling a happy tune while he cooked dinner.","vi":"Anh ấy vừa nấu bữa tối vừa huýt sáo một giai điệu vui tươi."},{"en":"I can remember the tune, but I''ve forgotten the words.","vi":"Tôi nhớ được giai điệu nhưng đã quên lời bài hát."},{"en":"That catchy tune has been stuck in my head all day.","vi":"Giai điệu dễ nhớ đó cứ lởn vởn trong đầu tôi cả ngày."}]', '[{"phrase":"catchy tune"},{"phrase":"out of tune"},{"phrase":"hum a tune"},{"phrase":"play a tune"}]', NULL, '/tuːn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tun/tune_/tune__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-07', 13, 'grass', 'cỏ; bãi cỏ', 'noun', '[{"en":"The children were sitting on the grass eating sandwiches.","vi":"Bọn trẻ đang ngồi trên bãi cỏ ăn bánh mì kẹp."},{"en":"My father cuts the grass in our garden every Sunday.","vi":"Bố tôi cắt cỏ trong vườn nhà vào mỗi Chủ nhật."},{"en":"Please keep off the grass while it is still wet.","vi":"Vui lòng không giẫm lên cỏ khi cỏ vẫn còn ướt."}]', '[{"phrase":"cut the grass"},{"phrase":"green grass"},{"phrase":"long grass"},{"phrase":"on the grass"}]', NULL, '/ɡræs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gra/grass/grass__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-07', 14, 'invitation', 'lời mời; thiệp mời', 'noun', '[{"en":"Thank you for the invitation to your birthday party.","vi":"Cảm ơn bạn đã mời tôi đến dự tiệc sinh nhật của bạn."},{"en":"We received a wedding invitation from our old neighbors.","vi":"Chúng tôi nhận được thiệp mời đám cưới từ những người hàng xóm cũ."},{"en":"She politely turned down his invitation to dinner.","vi":"Cô ấy lịch sự từ chối lời mời đi ăn tối của anh ấy."}]', '[{"phrase":"accept an invitation"},{"phrase":"wedding invitation"},{"phrase":"send an invitation"},{"phrase":"turn down an invitation"}]', 'invitation to sth', '/ˌɪnvɪˈteɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inv/invit/invitation__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-07', 15, 'transition', 'sự chuyển tiếp; sự chuyển đổi', 'noun', '[{"en":"The transition from school to work can be difficult.","vi":"Việc chuyển từ trường học sang đi làm có thể rất khó khăn."},{"en":"Our company is going through a period of transition.","vi":"Công ty chúng tôi đang trải qua một giai đoạn chuyển đổi."},{"en":"She made a smooth transition to her new role as manager.","vi":"Cô ấy đã chuyển sang vai trò quản lý mới một cách suôn sẻ."}]', '[{"phrase":"smooth transition"},{"phrase":"transition to"},{"phrase":"period of transition"},{"phrase":"make the transition"}]', NULL, '/trænˈzɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tra/trans/transition__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-07', 16, 'frighten', 'làm hoảng sợ; dọa', 'verb', '[{"en":"The loud thunder frightened the baby, and she started crying.","vi":"Tiếng sấm to làm em bé hoảng sợ và bé bắt đầu khóc."},{"en":"Don''t shout, or you''ll frighten the birds away.","vi":"Đừng hét lên, không thì bạn sẽ làm lũ chim sợ bay mất."},{"en":"Horror movies don''t frighten me, but spiders do.","vi":"Phim kinh dị không làm tôi sợ, nhưng nhện thì có."}]', '[{"phrase":"frighten away"},{"phrase":"frighten somebody to death"},{"phrase":"easily frightened"}]', NULL, '/ˈfraɪtn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fri/frigh/frighten__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-07', 17, 'bid', 'sự trả giá; sự dự thầu; nỗ lực (để đạt được)', 'noun', '[{"en":"He made a bid of two hundred dollars for the old clock.","vi":"Anh ấy trả giá hai trăm đô la cho chiếc đồng hồ cũ."},{"en":"Three companies put in a bid to build the new bridge.","vi":"Ba công ty đã nộp hồ sơ dự thầu xây cây cầu mới."},{"en":"The city failed in its bid to host the Olympic Games.","vi":"Thành phố đã thất bại trong nỗ lực đăng cai Thế vận hội."}]', '[{"phrase":"make a bid"},{"phrase":"winning bid"},{"phrase":"bid for"},{"phrase":"in a bid to"}]', NULL, '/ˈbɪd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-07', 18, 'breed', 'giống (vật nuôi); nhân giống, gây giống', 'noun', '[{"en":"What breed of dog is good for a small apartment?","vi":"Giống chó nào phù hợp với một căn hộ nhỏ?"},{"en":"This rare breed of cattle comes from the north.","vi":"Giống bò hiếm này có nguồn gốc từ miền Bắc."},{"en":"My uncle breeds horses on his farm in the countryside.","vi":"Chú tôi nuôi và nhân giống ngựa ở trang trại dưới quê."}]', '[{"phrase":"breed of dog"},{"phrase":"rare breed"},{"phrase":"breed horses"},{"phrase":"different breeds"}]', 'breed – bred – bred', '/briːd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bre/breed/breed__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-07', 19, 'extraordinary', 'phi thường; khác thường', 'adjective', '[{"en":"She has an extraordinary talent for music.","vi":"Cô ấy có năng khiếu âm nhạc phi thường."},{"en":"It was an extraordinary experience to see whales so close.","vi":"Được nhìn cá voi ở gần như vậy là một trải nghiệm phi thường."},{"en":"He wore an extraordinary hat covered in plastic flowers.","vi":"Anh ấy đội một chiếc mũ khác thường phủ đầy hoa nhựa."}]', '[{"phrase":"extraordinary talent"},{"phrase":"extraordinary experience"},{"phrase":"quite extraordinary"},{"phrase":"extraordinary story"}]', NULL, '/ɪkˈstrɔːrdəneri/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ext/extra/extraordinary__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-07', 20, 'brilliant', 'xuất sắc; tuyệt vời; rực rỡ', 'adjective', '[{"en":"What a brilliant idea for your sister''s birthday present!","vi":"Thật là một ý tưởng tuyệt vời cho món quà sinh nhật của chị bạn!"},{"en":"Our new math teacher is a brilliant young scientist.","vi":"Thầy dạy toán mới của chúng tôi là một nhà khoa học trẻ xuất sắc."},{"en":"We woke up to brilliant sunshine on the first day of our trip.","vi":"Chúng tôi thức dậy trong ánh nắng rực rỡ vào ngày đầu của chuyến đi."}]', '[{"phrase":"brilliant idea"},{"phrase":"brilliant career"},{"phrase":"brilliant sunshine"},{"phrase":"absolutely brilliant"}]', NULL, '/ˈbrɪliənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bri/brill/brilliant__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-07', 21, 'adviser', 'cố vấn; người tư vấn', 'noun', '[{"en":"I talked to a financial adviser before buying the house.","vi":"Tôi đã nói chuyện với một chuyên viên tư vấn tài chính trước khi mua nhà."},{"en":"My academic adviser helped me choose the right courses.","vi":"Cố vấn học tập đã giúp tôi chọn đúng các môn học."},{"en":"She works as a senior adviser to the company''s director.","vi":"Cô ấy làm cố vấn cấp cao cho giám đốc công ty."}]', '[{"phrase":"financial adviser"},{"phrase":"legal adviser"},{"phrase":"senior adviser"},{"phrase":"adviser to"}]', 'cũng viết: advisor', '/ədˈvaɪzər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/adv/advis/adviser__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-07', 22, 'stem', 'thân cây; cuống (hoa, lá)', 'noun', '[{"en":"Cut the flower stems before you put them in water.","vi":"Cắt bớt cuống hoa trước khi cắm vào nước."},{"en":"This plant has a thin green stem and small leaves.","vi":"Cây này có thân mảnh màu xanh và lá nhỏ."},{"en":"Hold the wine glass by its stem, not the bowl.","vi":"Hãy cầm ly rượu ở phần chân ly, đừng cầm vào bầu ly."}]', '[{"phrase":"flower stem"},{"phrase":"long stem"},{"phrase":"thin stem"}]', 'stem from: bắt nguồn từ', '/stem/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/ste/stem_/stem__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-07', 23, 'reverse', 'đảo ngược; hủy bỏ (quyết định)', 'verb', '[{"en":"The manager agreed to reverse his decision after the meeting.","vi":"Sau cuộc họp, quản lý đã đồng ý hủy bỏ quyết định của mình."},{"en":"It may be too late to reverse the damage to the forest.","vi":"Có lẽ đã quá muộn để đảo ngược thiệt hại cho khu rừng."},{"en":"Try reversing the order of the last two sentences.","vi":"Hãy thử đảo ngược thứ tự của hai câu cuối."}]', '[{"phrase":"reverse a decision"},{"phrase":"reverse the trend"},{"phrase":"reverse the damage"},{"phrase":"reverse the order"}]', 'in reverse: theo chiều ngược lại', '/rɪˈvɜːrs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rev/rever/reverse__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-07', 24, 'mode', 'chế độ; phương thức; cách thức', 'noun', '[{"en":"Please switch your phones to silent mode during the exam.","vi":"Vui lòng chuyển điện thoại sang chế độ im lặng trong giờ thi."},{"en":"For many students, the bicycle is the main mode of transport.","vi":"Với nhiều sinh viên, xe đạp là phương tiện đi lại chính."},{"en":"The camera has a special mode for taking photos at night.","vi":"Chiếc máy ảnh có một chế độ đặc biệt để chụp ảnh ban đêm."}]', '[{"phrase":"silent mode"},{"phrase":"mode of transport"},{"phrase":"night mode"},{"phrase":"sleep mode"}]', NULL, '/məʊd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mod/mode_/mode__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-07', 25, 'mirror', 'gương; gương chiếu hậu', 'noun', '[{"en":"She checked her hair in the mirror before leaving.","vi":"Cô ấy soi gương xem lại tóc trước khi ra ngoài."},{"en":"There''s a large mirror on the wall of the bathroom.","vi":"Có một chiếc gương lớn trên tường phòng tắm."},{"en":"Always look in your mirror before you change lanes.","vi":"Luôn nhìn gương chiếu hậu trước khi chuyển làn."}]', '[{"phrase":"look in the mirror"},{"phrase":"bathroom mirror"},{"phrase":"rear-view mirror"},{"phrase":"full-length mirror"}]', NULL, '/ˈmɪrər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mir/mirro/mirror__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-07', 26, 'awful', 'tồi tệ; kinh khủng', 'adjective', '[{"en":"The food at that hotel was absolutely awful.","vi":"Đồ ăn ở khách sạn đó thật sự tồi tệ."},{"en":"I feel awful about forgetting your birthday.","vi":"Tôi thấy thật tệ vì đã quên sinh nhật của bạn."},{"en":"We had awful weather for the whole week of our vacation.","vi":"Suốt cả tuần nghỉ lễ, thời tiết chỗ chúng tôi thật kinh khủng."}]', '[{"phrase":"feel awful"},{"phrase":"awful weather"},{"phrase":"absolutely awful"},{"phrase":"look awful"}]', NULL, '/ˈɔːfl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/awf/awful/awful__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-07', 27, 'pose', 'gây ra (mối đe dọa, vấn đề); đặt ra (câu hỏi); tạo dáng', 'verb', '[{"en":"Smoking poses a serious risk to your health.","vi":"Hút thuốc gây ra mối nguy hiểm nghiêm trọng cho sức khỏe của bạn."},{"en":"The new rules pose a problem for small businesses.","vi":"Các quy định mới đặt ra một vấn đề cho các doanh nghiệp nhỏ."},{"en":"The whole family posed for a photo in front of the lake.","vi":"Cả gia đình tạo dáng chụp ảnh trước hồ."}]', '[{"phrase":"pose a threat"},{"phrase":"pose a risk"},{"phrase":"pose a question"},{"phrase":"pose for a photo"}]', NULL, '/pəʊz/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pos/pose_/pose__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-07', 28, 'adjust', 'điều chỉnh; thích nghi', 'verb', '[{"en":"You can adjust the height of this chair with the lever.","vi":"Bạn có thể điều chỉnh độ cao của chiếc ghế này bằng cần gạt."},{"en":"It took me a few weeks to adjust to my new school.","vi":"Tôi mất vài tuần để thích nghi với trường mới."},{"en":"Let your eyes adjust to the dark before you move.","vi":"Hãy để mắt quen với bóng tối trước khi bạn di chuyển."}]', '[{"phrase":"adjust to"},{"phrase":"adjust the temperature"},{"phrase":"adjust the settings"},{"phrase":"quickly adjust"}]', 'adjust to sth: thích nghi với', '/əˈdʒʌst/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/adj/adjus/adjust__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-07', 29, 'creative', 'sáng tạo', 'adjective', '[{"en":"My sister is very creative and loves painting and writing.","vi":"Chị tôi rất sáng tạo và thích vẽ tranh lẫn viết lách."},{"en":"We need a creative way to solve this problem.","vi":"Chúng ta cần một cách sáng tạo để giải quyết vấn đề này."},{"en":"The course helps students develop their creative skills.","vi":"Khóa học giúp học viên phát triển các kỹ năng sáng tạo."}]', '[{"phrase":"creative thinking"},{"phrase":"creative writing"},{"phrase":"creative ideas"},{"phrase":"highly creative"}]', NULL, '/kriˈeɪtɪv/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cre/creat/creative__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-07', 30, 'nowadays', 'ngày nay; thời nay', 'adverb', '[{"en":"Nowadays, most people pay for things with their phones.","vi":"Ngày nay, hầu hết mọi người thanh toán bằng điện thoại."},{"en":"Children spend much more time indoors nowadays.","vi":"Thời nay trẻ em dành nhiều thời gian ở trong nhà hơn hẳn."},{"en":"Do you still play tennis nowadays, or have you stopped?","vi":"Dạo này bạn còn chơi quần vợt không, hay đã nghỉ rồi?"}]', '[{"phrase":"especially nowadays"},{"phrase":"nowadays, most people"}]', NULL, '/ˈnaʊədeɪz/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/now/nowad/nowadays__us_1.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-5-08', 'ngsl-5', 'Thông dụng 2.001–2.500 · Bộ 8', 'New General Service List, thứ hạng 2.001–2.500', '#3da9fc', 'BookOpen', 8);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-08', 1, 'poem', 'bài thơ', 'noun', '[{"en":"My daughter wrote a short poem about her grandmother.","vi":"Con gái tôi đã viết một bài thơ ngắn về bà của cháu."},{"en":"Can you read the poem aloud to the class?","vi":"Em có thể đọc to bài thơ cho cả lớp nghe không?"},{"en":"We had to learn three poems by heart for the exam.","vi":"Chúng tôi phải học thuộc lòng ba bài thơ cho kỳ thi."}]', '[{"phrase":"write a poem"},{"phrase":"read a poem"},{"phrase":"love poem"},{"phrase":"short poem"}]', NULL, '/ˈpəʊəm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/poe/poem_/poem__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-08', 2, 'agricultural', '(thuộc) nông nghiệp', 'adjective', '[{"en":"Most of the land around our village is used for agricultural purposes.","vi":"Phần lớn đất quanh làng tôi được dùng vào mục đích nông nghiệp."},{"en":"Rice is the country''s most important agricultural product.","vi":"Lúa gạo là nông sản quan trọng nhất của đất nước."},{"en":"He studied agricultural science before returning to run the family farm.","vi":"Anh ấy học ngành khoa học nông nghiệp trước khi về quản lý trang trại của gia đình."}]', '[{"phrase":"agricultural land"},{"phrase":"agricultural products"},{"phrase":"agricultural production"},{"phrase":"agricultural sector"}]', NULL, '/ˌæɡrɪˈkʌltʃərəl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/agr/agric/agricultural__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-08', 3, 'competitor', 'đối thủ cạnh tranh; đấu thủ', 'noun', '[{"en":"Our prices are lower than those of our main competitors.","vi":"Giá của chúng tôi thấp hơn giá của các đối thủ cạnh tranh chính."},{"en":"The company lost many customers to a new competitor last year.","vi":"Năm ngoái công ty đã mất nhiều khách hàng vào tay một đối thủ mới."},{"en":"More than two hundred competitors took part in the race.","vi":"Hơn hai trăm đấu thủ đã tham gia cuộc đua."}]', '[{"phrase":"main competitor"},{"phrase":"major competitor"},{"phrase":"direct competitor"}]', NULL, '/kəmˈpetɪtər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/compe/competitor__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-08', 4, 'alcohol', 'rượu bia; cồn', 'noun', '[{"en":"My father stopped drinking alcohol after his heart problems.","vi":"Bố tôi đã bỏ rượu bia sau khi bị bệnh tim."},{"en":"You shouldn''t drive if you have had any alcohol.","vi":"Bạn không nên lái xe nếu đã uống chút rượu bia nào."},{"en":"Clean the cut with a little alcohol before putting on a bandage.","vi":"Hãy lau vết cắt bằng một chút cồn trước khi băng lại."}]', '[{"phrase":"drink alcohol"},{"phrase":"alcohol consumption"},{"phrase":"alcohol-free"}]', 'không đếm được', '/ˈælkəhɔːl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/alc/alcoh/alcohol__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-08', 5, 'festival', 'lễ hội; liên hoan', 'noun', '[{"en":"Thousands of people come to the town for the summer music festival.","vi":"Hàng nghìn người đến thị trấn dự lễ hội âm nhạc mùa hè."},{"en":"Children carry colorful lanterns during the Mid-Autumn Festival.","vi":"Trẻ em rước những chiếc đèn lồng đầy màu sắc trong dịp Tết Trung thu."},{"en":"Her short film won a prize at an international film festival.","vi":"Phim ngắn của cô ấy đã đoạt giải tại một liên hoan phim quốc tế."}]', '[{"phrase":"music festival"},{"phrase":"film festival"},{"phrase":"hold a festival"}]', NULL, '/ˈfestɪvl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fes/festi/festival__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-08', 6, 'vegetable', 'rau; rau củ', 'noun', '[{"en":"Try to eat more fresh fruit and vegetables every day.","vi":"Hãy cố gắng ăn nhiều trái cây và rau tươi hơn mỗi ngày."},{"en":"My grandmother grows vegetables in a small garden behind her house.","vi":"Bà tôi trồng rau trong một mảnh vườn nhỏ sau nhà."},{"en":"Is this soup made with any meat, or only vegetables?","vi":"Món súp này có nấu với thịt không, hay chỉ có rau củ?"}]', '[{"phrase":"fresh vegetables"},{"phrase":"grow vegetables"},{"phrase":"fruit and vegetables"},{"phrase":"vegetable soup"}]', NULL, '/ˈvedʒtəbl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/veg/veget/vegetable__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-08', 7, 'van', 'xe tải nhỏ; xe van', 'noun', '[{"en":"We rented a van to move our furniture to the new apartment.","vi":"Chúng tôi đã thuê một chiếc xe tải nhỏ để chuyển đồ đạc sang căn hộ mới."},{"en":"A delivery van is parked in front of the building.","vi":"Một chiếc xe giao hàng đang đậu trước tòa nhà."},{"en":"He drives a van for a small bakery in town.","vi":"Anh ấy lái xe van cho một tiệm bánh nhỏ trong thị trấn."}]', '[{"phrase":"delivery van"},{"phrase":"drive a van"},{"phrase":"police van"}]', NULL, '/væn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/van/van__/van__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-08', 8, 'confident', 'tự tin; tin chắc', 'adjective', '[{"en":"She felt much more confident after practicing her speech several times.","vi":"Cô ấy cảm thấy tự tin hơn nhiều sau khi tập bài phát biểu vài lần."},{"en":"I''m confident that we will finish the project on time.","vi":"Tôi tin chắc rằng chúng ta sẽ hoàn thành dự án đúng hạn."},{"en":"Are you confident enough to speak English with foreign customers?","vi":"Bạn có đủ tự tin để nói tiếng Anh với khách nước ngoài không?"}]', '[{"phrase":"feel confident"},{"phrase":"confident that"},{"phrase":"confident about"}]', NULL, '/ˈkɑːnfɪdənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xconf/xconfident__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-08', 9, 'planet', 'hành tinh; Trái Đất', 'noun', '[{"en":"Mars is the fourth planet from the sun.","vi":"Sao Hỏa là hành tinh thứ tư tính từ Mặt Trời."},{"en":"We all need to do more to protect the planet.","vi":"Tất cả chúng ta cần làm nhiều hơn để bảo vệ Trái Đất."},{"en":"Scientists have discovered a new planet far outside our solar system.","vi":"Các nhà khoa học đã phát hiện một hành tinh mới ở rất xa ngoài hệ Mặt Trời."}]', '[{"phrase":"save the planet"},{"phrase":"protect the planet"},{"phrase":"distant planet"}]', NULL, '/ˈplænɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pla/plane/planet__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-08', 10, 'curve', 'đường cong; khúc cua', 'noun', '[{"en":"The river makes a wide curve around the old town.","vi":"Dòng sông uốn một đường cong rộng quanh khu phố cổ."},{"en":"Slow down, there''s a sharp curve in the road ahead.","vi":"Chậm lại đi, phía trước có một khúc cua gấp."},{"en":"The bus took the curve too fast and almost left the road.","vi":"Chiếc xe buýt vào cua quá nhanh và suýt lao ra khỏi đường."}]', '[{"phrase":"sharp curve"},{"phrase":"gentle curve"},{"phrase":"learning curve"}]', NULL, '/kɜːrv/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cur/curve/curve__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-08', 11, 'knee', 'đầu gối', 'noun', '[{"en":"He hurt his knee while playing football on Saturday.","vi":"Anh ấy bị đau đầu gối khi chơi bóng đá hôm thứ Bảy."},{"en":"The little boy sat on his father''s knee and listened to the story.","vi":"Cậu bé ngồi trên đầu gối bố và nghe kể chuyện."},{"en":"My knees start to ache when I walk up too many stairs.","vi":"Đầu gối tôi bắt đầu đau nhức khi leo quá nhiều bậc thang."}]', '[{"phrase":"knee injury"},{"phrase":"bend your knees"},{"phrase":"on your knees"}]', NULL, '/niː/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/k/kne/knee_/knee__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-08', 12, 'overcome', 'vượt qua; khắc phục', 'verb', '[{"en":"She worked hard to overcome her fear of speaking in public.","vi":"Cô ấy đã rất cố gắng để vượt qua nỗi sợ nói trước đám đông."},{"en":"Together we can overcome any difficulties that come our way.","vi":"Cùng nhau, chúng ta có thể vượt qua mọi khó khăn gặp phải."},{"en":"The team overcame several technical problems to launch the app on time.","vi":"Nhóm đã khắc phục một số sự cố kỹ thuật để ra mắt ứng dụng đúng hạn."}]', '[{"phrase":"overcome a problem"},{"phrase":"overcome difficulties"},{"phrase":"overcome fear"},{"phrase":"overcome obstacles"}]', 'overcome – overcame – overcome', '/ˌəʊvərˈkʌm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/ove/overc/overcome__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-08', 13, 'web', 'mạng (Internet); mạng nhện', 'noun', '[{"en":"You can find the train timetable on the web.","vi":"Bạn có thể tìm lịch tàu chạy trên mạng."},{"en":"My brother designs web pages for small businesses.","vi":"Anh tôi thiết kế trang web cho các doanh nghiệp nhỏ."},{"en":"A large spider had built a web in the corner of the window.","vi":"Một con nhện lớn đã giăng mạng ở góc cửa sổ."}]', '[{"phrase":"on the web"},{"phrase":"web page"},{"phrase":"web browser"},{"phrase":"spider''s web"}]', NULL, '/web/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/web/web__/web__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-08', 14, 'depth', 'độ sâu; chiều sâu', 'noun', '[{"en":"The lake reaches a depth of about thirty meters in the middle.","vi":"Ở giữa, hồ có độ sâu khoảng ba mươi mét."},{"en":"Measure the height, width and depth of the box before you order it.","vi":"Hãy đo chiều cao, chiều rộng và chiều sâu của chiếc hộp trước khi đặt mua."},{"en":"We need to discuss this issue in more depth at the next meeting.","vi":"Chúng ta cần thảo luận vấn đề này sâu hơn trong buổi họp tới."}]', '[{"phrase":"in depth"},{"phrase":"a depth of"},{"phrase":"depth of knowledge"}]', NULL, '/depθ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dep/depth/depth__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-08', 15, 'entrance', 'lối vào; sự vào, sự nhập học', 'noun', '[{"en":"I''ll wait for you at the main entrance of the hospital.","vi":"Mình sẽ đợi bạn ở lối vào chính của bệnh viện."},{"en":"The entrance to the museum is on the other side of the street.","vi":"Lối vào bảo tàng ở phía bên kia đường."},{"en":"He studied very hard to pass the university entrance exam.","vi":"Cậu ấy đã học rất chăm để thi đỗ kỳ thi tuyển sinh đại học."}]', '[{"phrase":"main entrance"},{"phrase":"front entrance"},{"phrase":"entrance to"},{"phrase":"entrance exam"}]', NULL, '/ˈɛntrəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-08', 16, 'log', 'khúc gỗ; nhật ký (ghi chép)', 'noun', '[{"en":"We sat on a log and warmed our hands by the fire.","vi":"Chúng tôi ngồi trên một khúc gỗ và hơ tay bên đống lửa."},{"en":"He put another log on the fire before going to bed.","vi":"Anh ấy cho thêm một khúc gỗ vào lửa trước khi đi ngủ."},{"en":"Drivers must keep a log of every trip they make.","vi":"Tài xế phải ghi nhật ký mọi chuyến đi của mình."}]', '[{"phrase":"keep a log"},{"phrase":"log fire"},{"phrase":"fallen log"}]', 'cụm động từ: log in / log out (đăng nhập / đăng xuất)', '/lɔːɡ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/log/log__/log__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-08', 17, 'giant', 'khổng lồ; to lớn', 'adjective', '[{"en":"A giant screen showed the football match in the town square.","vi":"Một màn hình khổng lồ chiếu trận bóng đá ở quảng trường thị trấn."},{"en":"The kids were amazed by the giant turtles at the zoo.","vi":"Bọn trẻ thích thú với những con rùa khổng lồ ở sở thú."},{"en":"Moving to another country was a giant step for our family.","vi":"Chuyển sang nước khác sống là một bước tiến lớn đối với gia đình tôi."}]', '[{"phrase":"giant screen"},{"phrase":"giant step"},{"phrase":"giant panda"}]', 'cũng là danh từ: người khổng lồ; tập đoàn lớn (tech giant)', '/ˈdʒaɪənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gia/giant/giant__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-08', 18, 'god', 'thần; vị thần', 'noun', '[{"en":"In the old story, the god of the sea was very angry.","vi":"Trong câu chuyện xưa, thần biển đã rất tức giận."},{"en":"The ancient Greeks believed that many gods lived on a high mountain.","vi":"Người Hy Lạp cổ đại tin rằng nhiều vị thần sống trên một ngọn núi cao."},{"en":"The children read a book of myths about gods and heroes.","vi":"Bọn trẻ đọc một cuốn sách thần thoại về các vị thần và anh hùng."}]', '[{"phrase":"the god of"},{"phrase":"ancient gods"},{"phrase":"gods and goddesses"}]', 'God (viết hoa) = Chúa, Thượng đế', '/ɡɑːd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/god/god__/god__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-08', 19, 'portion', 'phần; suất (ăn)', 'noun', '[{"en":"The portions at that restaurant are big enough for two people.","vi":"Suất ăn ở nhà hàng đó đủ lớn cho hai người."},{"en":"A large portion of my salary goes on rent.","vi":"Một phần lớn tiền lương của tôi dùng để trả tiền nhà."},{"en":"Only a small portion of the road was damaged by the storm.","vi":"Chỉ một phần nhỏ con đường bị bão làm hư hại."}]', '[{"phrase":"large portion"},{"phrase":"small portion"},{"phrase":"portion of"},{"phrase":"portion size"}]', NULL, '/ˈpɔːrʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/por/porti/portion__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-08', 20, 'substance', 'chất; thực chất, nội dung', 'noun', '[{"en":"Keep dangerous substances out of the reach of children.","vi":"Hãy để các chất nguy hiểm xa tầm tay trẻ em."},{"en":"The scientists found a strange white substance on the rocks.","vi":"Các nhà khoa học tìm thấy một chất màu trắng lạ trên những tảng đá."},{"en":"His speech sounded good but had very little substance.","vi":"Bài phát biểu của anh ta nghe hay nhưng có rất ít nội dung thực chất."}]', '[{"phrase":"dangerous substance"},{"phrase":"chemical substance"},{"phrase":"harmful substances"}]', NULL, '/ˈsʌbstəns/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sub/subst/substance__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-08', 21, 'extensive', 'rộng lớn; sâu rộng, nhiều', 'adjective', '[{"en":"The hotel has extensive gardens with a pool and tennis courts.","vi":"Khách sạn có khu vườn rộng lớn với hồ bơi và sân quần vợt."},{"en":"She has extensive experience in teaching young children.","vi":"Cô ấy có nhiều kinh nghiệm dạy trẻ nhỏ."},{"en":"The storm caused extensive damage to houses along the coast.","vi":"Cơn bão đã gây thiệt hại trên diện rộng cho nhà cửa dọc bờ biển."}]', '[{"phrase":"extensive experience"},{"phrase":"extensive damage"},{"phrase":"extensive research"},{"phrase":"extensive knowledge"}]', NULL, '/ɪkˈstensɪv/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ext/exten/extensive__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-08', 22, 'interpret', 'hiểu, giải thích; phiên dịch', 'verb', '[{"en":"I really didn''t know how to interpret his silence.","vi":"Tôi thật sự không biết phải hiểu sự im lặng của anh ấy thế nào."},{"en":"Doctors are trained to interpret the results of blood tests.","vi":"Bác sĩ được đào tạo để giải thích kết quả xét nghiệm máu."},{"en":"My cousin interpreted for us when we went shopping in Japan.","vi":"Anh họ tôi phiên dịch giúp chúng tôi khi đi mua sắm ở Nhật."}]', '[{"phrase":"interpret data"},{"phrase":"interpret the results"},{"phrase":"interpret as"}]', NULL, '/ɪnˈtɜːrprət/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/int/inter/interpret__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-08', 23, 'independence', 'sự độc lập; sự tự lập', 'noun', '[{"en":"Getting my first job gave me a real sense of independence.","vi":"Có công việc đầu tiên mang lại cho tôi cảm giác tự lập thực sự."},{"en":"Many teenagers want more independence from their parents.","vi":"Nhiều thanh thiếu niên muốn được độc lập hơn với bố mẹ."},{"en":"Moving out helped her gain financial independence at a young age.","vi":"Ra ở riêng đã giúp cô ấy độc lập về tài chính từ khi còn trẻ."}]', '[{"phrase":"financial independence"},{"phrase":"sense of independence"},{"phrase":"gain independence"},{"phrase":"independence from"}]', NULL, '/ˌɪndɪˈpendəns/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ind/indep/independence__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-08', 24, 'sugar', 'đường', 'noun', '[{"en":"Do you take sugar in your coffee or tea?","vi":"Bạn có cho đường vào cà phê hay trà không?"},{"en":"Mix the butter and sugar together until the mixture is soft.","vi":"Trộn bơ với đường cho đến khi hỗn hợp mềm."},{"en":"The doctor told me to cut down on sugar and salt.","vi":"Bác sĩ bảo tôi nên ăn bớt đường và muối."}]', '[{"phrase":"brown sugar"},{"phrase":"add sugar"},{"phrase":"cut down on sugar"}]', 'không đếm được (a spoonful of sugar)', '/ˈʃʊɡər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sug/sugar/sugar__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-08', 25, 'inner', 'bên trong; nội tâm', 'adjective', '[{"en":"Put your wallet in the inner pocket of your jacket.","vi":"Hãy cất ví vào túi trong của áo khoác."},{"en":"The inner walls of the old house were painted white.","vi":"Các bức tường bên trong ngôi nhà cũ được sơn màu trắng."},{"en":"Yoga helps me find inner peace after a busy day.","vi":"Yoga giúp tôi tìm lại sự bình yên trong tâm hồn sau một ngày bận rộn."}]', '[{"phrase":"inner city"},{"phrase":"inner peace"},{"phrase":"inner pocket"},{"phrase":"inner circle"}]', 'inner ≠ outer (bên ngoài)', '/ˈɪnər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inn/inner/inner__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-08', 26, 'harm', 'sự tổn hại; điều có hại', 'noun', '[{"en":"A little extra rest won''t do you any harm.","vi":"Nghỉ ngơi thêm một chút cũng chẳng hại gì cho bạn."},{"en":"Too much sun can cause serious harm to your skin.","vi":"Phơi nắng quá nhiều có thể gây hại nghiêm trọng cho da."},{"en":"Don''t worry, the dog is friendly and means no harm.","vi":"Đừng lo, con chó thân thiện và không có ý làm hại ai đâu."}]', '[{"phrase":"do harm"},{"phrase":"cause harm"},{"phrase":"no harm done"},{"phrase":"mean no harm"}]', 'cũng là động từ: harm (làm hại)', '/hɑːrm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/har/harm_/harm__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-08', 27, 'consult', 'hỏi ý kiến; tra cứu', 'verb', '[{"en":"You should consult a doctor if the pain doesn''t go away.","vi":"Bạn nên hỏi ý kiến bác sĩ nếu cơn đau không hết."},{"en":"My boss made the decision without consulting anyone on the team.","vi":"Sếp tôi đã quyết định mà không hỏi ý kiến ai trong nhóm."},{"en":"She consulted the map to find the quickest way home.","vi":"Cô ấy tra bản đồ để tìm đường về nhà nhanh nhất."}]', '[{"phrase":"consult a doctor"},{"phrase":"consult a lawyer"},{"phrase":"consult with"},{"phrase":"consult a dictionary"}]', NULL, '/kənˈsʌlt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcons/xconsult__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-08', 28, 'pink', '(màu) hồng', 'adjective', '[{"en":"My little sister wants to paint her bedroom walls pink.","vi":"Em gái tôi muốn sơn tường phòng ngủ màu hồng."},{"en":"She wore a pale pink dress to her friend''s wedding.","vi":"Cô ấy mặc một chiếc váy hồng nhạt đến đám cưới bạn."},{"en":"The sky turned pink as the sun went down.","vi":"Bầu trời chuyển sang màu hồng khi mặt trời lặn."}]', '[{"phrase":"pale pink"},{"phrase":"bright pink"},{"phrase":"turn pink"},{"phrase":"light pink"}]', NULL, '/pɪŋk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pin/pink_/pink__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-08', 29, 'shadow', 'bóng; bóng tối', 'noun', '[{"en":"In the late afternoon, the trees cast long shadows across the grass.","vi":"Vào cuối chiều, cây cối đổ những chiếc bóng dài trên bãi cỏ."},{"en":"The cat was hiding in the shadows under the car.","vi":"Con mèo đang nấp trong bóng tối dưới gầm xe."},{"en":"My son is scared of his own shadow on the wall at night.","vi":"Con trai tôi sợ chính cái bóng của mình trên tường vào ban đêm."}]', '[{"phrase":"cast a shadow"},{"phrase":"long shadows"},{"phrase":"in the shadows"},{"phrase":"dark shadow"}]', NULL, '/ˈʃædəʊ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sha/shado/shadow__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-08', 30, 'strip', 'dải; mảnh dài', 'noun', '[{"en":"Cut the chicken into thin strips before you fry it.","vi":"Thái thịt gà thành từng dải mỏng trước khi chiên."},{"en":"There is a narrow strip of sand between the hotel and the sea.","vi":"Có một dải cát hẹp giữa khách sạn và biển."},{"en":"He tied the top of the bag with a strip of cloth.","vi":"Anh ấy buộc miệng túi bằng một mảnh vải dài."}]', '[{"phrase":"thin strip"},{"phrase":"narrow strip"},{"phrase":"strip of land"},{"phrase":"strip of paper"}]', 'cũng là động từ: strip (lột, cởi bỏ)', '/strɪp/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/str/strip/strip__us_1.mp3', NULL, NULL);
